window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[225]={"id":"225","numero":225,"titre":"Artériopathies de l'aorte, des artères viscérales et des MI","objectifs":[{"id":"225-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition et la fréquence de l’artériopathie oblitérante des membres inférieurs (AOMI)","contenu":"<p>L'<span class=\"kw-def\">AOMI</span> est définie par la présence de <span class=\"kw-def\">lésions d'athérosclérose de l'aorte et des artères des membres inférieurs</span>, pouvant entraîner des <span class=\"kw-clinique\">plaques</span>, des <span class=\"kw-clinique\">sténoses</span> ou des <span class=\"kw-clinique\">obstructions</span> athéromateuses d'une ou plusieurs artères destinées aux membres inférieurs. Elle représente l'<span class=\"kw-def\">expression locale d'une maladie systémique</span> : le <span class=\"kw-def\">pronostic</span> est en grande partie conditionné par les complications cardiaques et cérébrovasculaires.</p>\n      <p>L'origine athéromateuse domine très largement : l'AOMI correspond à <span class=\"kw-chiffre\">&gt; 95 %</span> des atteintes artérielles oblitérantes des membres inférieurs.</p>\n      <p><strong>Fréquence</strong> — la <span class=\"kw-def\">prévalence</span> augmente avec l'âge et atteint <span class=\"kw-chiffre\">&gt; 20 %</span> au-delà de <span class=\"kw-chiffre\">70 ans</span>. Elle doit être <strong>recherchée systématiquement</strong> à partir de <span class=\"kw-chiffre\">60 ans</span>.</p>\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-def\">Pronostic</span></th><th>Donnée chiffrée</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Claudication</span> intermittente</td><td>Espérance de vie réduite en moyenne de <span class=\"kw-chiffre\">-10 ans</span></td></tr>\n          <tr><td><span class=\"kw-def\">Stade</span> d'ischémie d'effort (<span class=\"kw-clinique\">claudication</span>)</td><td><span class=\"kw-def\">Mortalité</span> <span class=\"kw-alerte\">15 % à 5 ans</span></td></tr>\n          <tr><td><span class=\"kw-def\">Stade</span> d'ischémie permanente chronique (symptômes de repos)</td><td><span class=\"kw-def\">Mortalité</span> <span class=\"kw-alerte\">25 % à 1 an</span> et <span class=\"kw-alerte\">70 % à 5 ans</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 221 — <span class=\"kw-etio\">Athérome</span></em></p>","frequence":0},{"id":"225-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître l’étiologie et les facteurs de risque de l’AOMI","contenu":"<p>L'<span class=\"kw-etio\">origine athéromateuse</span> de l'AOMI est de très loin la plus fréquente (<span class=\"kw-chiffre\">&gt; 95 %</span>). L'AOMI est l'expression locale d'une maladie systémique : son <span class=\"kw-def\">pronostic</span> est conditionné par les atteintes <span class=\"kw-alerte\">cardiaques</span> (<span class=\"kw-etio\">angor</span>, <span class=\"kw-etio\">infarctus du myocarde</span>) et <span class=\"kw-alerte\">cérébrovasculaires</span> associées.</p>\n      <p><strong><span class=\"kw-def\">Facteurs de risque</span></strong> — ce sont les <span class=\"kw-def\">facteurs de risque cardiovasculaire</span> : âge, <span class=\"kw-clinique\">tabac</span>, <span class=\"kw-clinique\">diabète</span>, <span class=\"kw-def\">HTA</span>, <span class=\"kw-etio\">hypercholestérolémie</span>. Les <strong>FR dominants</strong> de l'AOMI sont le <span class=\"kw-alerte\">tabac</span> et le <span class=\"kw-alerte\">diabète</span>.</p>\n      <p><strong>Artériopathies non athéromateuses</strong> — elles représentent moins de <span class=\"kw-chiffre\">5 %</span> des atteintes oblitérantes des membres inférieurs :</p>\n      <ul>\n        <li><strong>Artériopathies inflammatoires :</strong> maladie de <span class=\"kw-etio\">Buerger</span>, <span class=\"kw-etio\">Takayasu</span>, <span class=\"kw-etio\">Horton</span>, certaines collagénoses (périartérite noueuse, <span class=\"kw-etio\">lupus</span>).</li>\n        <li><strong>Dysplasie fibromusculaire :</strong> au niveau iliaque ou poplité.</li>\n        <li><strong>Coarctation de l'aorte :</strong> cause d'hypodébit en aval.</li>\n        <li><strong>Atteintes acquises :</strong> post-radiques, post-traumatiques, toxiques (dérivés de l'ergot de seigle), gelures, compressions extrinsèques.</li>\n        <li><strong>Atteintes spécifiques de l'artère poplitée :</strong> artère poplitée piégée, kyste poplité sous-adventiciel.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 221 — <span class=\"kw-etio\">Athérome</span> · 223 — <span class=\"kw-etio\">Dyslipidémie</span> · 224 — <span class=\"kw-def\">HTA</span> · 247 — <span class=\"kw-def\">Diabète</span> · 75 — Addiction <span class=\"kw-etio\">Tabac</span></em></p>","frequence":0},{"id":"225-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les manifestations cliniques et la classification de l’AOMI et savoir évoquer les diagnostics différentiels","contenu":"<p>Les chirurgiens vasculaires utilisent une <span class=\"kw-def\">classification clinico-hémodynamique</span> en 3 stades. La <span class=\"kw-def\">classification</span> de <span class=\"kw-def\">Leriche &amp; Fontaine</span> est <strong>abandonnée</strong> (faussement rassurante, basée uniquement sur les symptômes et suggérant une succession chronologique erronée) — mais elle reste à connaître.</p>\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-def\">Stade</span></th><th>Clinique</th><th>Hémodynamique</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Asymptomatique</strong></td><td>Aucun symptôme</td><td><span class=\"kw-bio\">IPS ≤ 0,9</span> ; PA cheville <span class=\"kw-chiffre\">&gt; 50 mmHg</span></td></tr>\n          <tr><td><strong>Ischémie d'effort</strong></td><td><span class=\"kw-clinique\">Claudication intermittente</span></td><td><span class=\"kw-bio\">IPS ≤ 0,9</span> ; PA cheville <span class=\"kw-chiffre\">&gt; 50 mmHg</span></td></tr>\n          <tr><td><strong>Ischémie permanente</strong></td><td><span class=\"kw-clinique\">Douleurs de décubitus</span> au repos ± <span class=\"kw-clinique\">troubles trophiques</span></td><td><span class=\"kw-bio\">IPS ≤ 0,9</span> ; PA cheville <span class=\"kw-alerte\">≤ 50 mmHg</span> ; pression d'orteil <span class=\"kw-alerte\">&lt; 30 mmHg</span> ; <span class=\"kw-bio\">TcPO2 &lt; 30 mmHg</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Classifications historiques</strong> (à connaître). <span class=\"kw-def\">Leriche &amp; Fontaine</span> — 4 stades : I asymptomatique · II <span class=\"kw-clinique\">claudication</span> (ischémie d'effort) · III <span class=\"kw-clinique\">douleur de repos</span> (ischémie critique) · IV <span class=\"kw-clinique\">ulcération ou gangrène</span>. <span class=\"kw-def\">Rutherford</span> — plus détaillée, grades 0 à III avec catégories 0 à 6. La dichotomie <span class=\"kw-alerte\">ischémie aiguë</span> / chronique se fait sur un <strong>cut-off à <span class=\"kw-chiffre\">15 jours</span></strong>.</p>\n\n      <h4 style=\"margin:16px 0 6px;font-size:14px;\"><span class=\"kw-def\">Stade</span> 1 — forme asymptomatique</h4>\n      <p>À évoquer devant un <span class=\"kw-clinique\">souffle vasculaire</span> ou une <span class=\"kw-clinique\">abolition de pouls périphériques</span> chez un sujet à <span class=\"kw-etio\">FRCV</span>, ou une <span class=\"kw-clinique\">dysfonction érectile</span> chez un patient à FRCV. Confirmation : <span class=\"kw-bio\">IPS ≤ 0,90</span>.</p>\n      <div class=\"callout callout-warn\">\n        <strong>Piège — la forme masquée.</strong> Une atteinte sévère peut rester asymptomatique : développement d'une <span class=\"kw-clinique\">circulation collatérale</span>, sujet âgé peu mobile, <span class=\"kw-clinique\">neuropathie</span> (<span class=\"kw-def\">diabète</span>, <span class=\"kw-def\">IRC</span>) altérant la sensibilité. Le patient peut alors présenter d'emblée une <span class=\"kw-alerte\">forme grave d'ischémie permanente</span> en paraissant asymptomatique peu de temps avant.\n      </div>\n\n      <h4 style=\"margin:16px 0 6px;font-size:14px;\"><span class=\"kw-def\">Stade</span> 2 — ischémie d'effort (<span class=\"kw-clinique\">claudication</span> intermittente)</h4>\n      <ul>\n        <li><strong>Type :</strong> <span class=\"kw-clinique\">crampe</span>.</li>\n        <li><strong>Topographie :</strong> <span class=\"kw-clinique\">mollet</span> typiquement.</li>\n        <li><strong>Distance de gêne :</strong> distance à laquelle la douleur apparaît ; <strong>distance de marche :</strong> distance à laquelle la douleur oblige à l'arrêt — <span class=\"kw-alerte\">AOMI sévère si distance de marche &lt; 100 m sur terrain plat</span>.</li>\n        <li><strong>Disparition :</strong> habituellement en <span class=\"kw-chiffre\">&lt; 5 minutes</span> à l'arrêt.</li>\n      </ul>\n      <p>Formes atypiques fréquentes : distances variables, topographies autres (pied, cuisse, <span class=\"kw-clinique\">claudication fessière</span> par atteinte aorto-iliaque), paresthésie d'effort, ralentissement du pas sans arrêt obligé.</p>\n\n      <h4 style=\"margin:16px 0 6px;font-size:14px;\">Stades 3-4 — ischémie permanente / critique</h4>\n      <ul>\n        <li><strong>Douleur de repos (<span class=\"kw-def\">stade</span> 3) :</strong> à type de <span class=\"kw-clinique\">brûlure</span> ; topographie <span class=\"kw-clinique\">orteil / avant-pied</span> ; survient après quelques minutes à quelques heures de décubitus ; <span class=\"kw-clinique\">calmée en position déclive</span> (jambes pendantes au bord du lit).</li>\n        <li><strong>Troubles trophiques (<span class=\"kw-def\">stade</span> 4) :</strong> peau mince et fragile, dépilation ; <span class=\"kw-clinique\">ulcère artériel</span> ; <span class=\"kw-clinique\">gangrène</span> (orteils, talon) ; portes d'entrée infectieuses.</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong>Ischémie permanente — <span class=\"kw-def\">pronostic</span> du membre engagé.</strong> Douleurs durant <span class=\"kw-chiffre\">&gt; 15 jours</span>, résistant aux <span class=\"kw-ttt\">antalgiques</span> usuels ; pressions de perfusion effondrées (<span class=\"kw-alerte\">&lt; 50 mmHg</span> à la cheville, <span class=\"kw-alerte\">&lt; 30 mmHg</span> à l'hallux). Haut risque d'<span class=\"kw-alerte\">amputation</span> en l'absence de <span class=\"kw-ttt\">revascularisation</span>.\n      </div>\n\n      <h4 style=\"margin:16px 0 6px;font-size:14px;\">Localiser la sténose ou l'obstruction</h4>\n      <p>Une <strong>sténose</strong> donne un <span class=\"kw-clinique\">souffle</span> ; une <strong>obstruction</strong> donne une <span class=\"kw-clinique\">abolition de pouls en aval</span> sans souffle. Le siège de la douleur oriente vers l'artère atteinte :</p>\n      <table >\n        <thead>\n          <tr><th>Siège de la douleur</th><th>Artère en cause</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Fesse</td><td>Artère iliaque commune ou iliaque interne (hypogastrique)</td></tr>\n          <tr><td>Cuisse</td><td>Artère iliaque externe ou fémorale commune</td></tr>\n          <tr><td>Mollet</td><td>Artère fémorale superficielle ou poplitée</td></tr>\n          <tr><td>Pied</td><td>Artères du pied ou de la jambe</td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/225/arbre-arteriel-membre-inferieur.png\" alt=\"Schéma de l'arbre artériel du membre inférieur : iliaque commune, fémorale, poplitée, artères tibiales\" loading=\"lazy\">\n        <figcaption>Arbre artériel du membre inférieur — le siège de la <span class=\"kw-clinique\">claudication</span> renseigne sur le niveau de la <span class=\"kw-clinique\">lésion</span>. Source : fiche source EDN item 225.</figcaption>\n      </figure>\n      <p><strong><span class=\"kw-clinique\">Syndrome de Leriche</span></strong> — atteinte <span class=\"kw-def\">aorto-iliaque</span> (aorte sous-rénale + artères iliaques primitives) associant : <span class=\"kw-clinique\">claudication fessière bilatérale</span> et/ou fatigabilité à la marche, <span class=\"kw-clinique\">dysfonction érectile</span> chez l'homme, <span class=\"kw-clinique\">abolition des 2 pouls fémoraux</span> et atrophie musculaire des membres inférieurs.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/225/arteres-pelviennes.png\" alt=\"Schéma des artères pelviennes : aorte abdominale, iliaques commune et externe, fémorale commune\" loading=\"lazy\">\n        <figcaption>Artères pelviennes et aorto-iliaques — territoire du syndrome de Leriche. Source : fiche source EDN item 225.</figcaption>\n      </figure>\n\n      <h4 style=\"margin:16px 0 6px;font-size:14px;\"><span class=\"kw-clinique\">Ulcère artériel</span> <span class=\"kw-bio\">vs</span> <span class=\"kw-clinique\">ulcère veineux</span> (pivot EDN)</h4>\n      <table >\n        <thead>\n          <tr><th></th><th>Ulcère veineux</th><th>Ulcère artériel</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Terrain</span></td><td>Femme &gt;<span class=\"kw-chiffre\"> 50 ans</span> ; ATCD de <span class=\"kw-def\">TVP</span>, varices, <span class=\"kw-etio\">surpoids</span></td><td>Homme &gt;<span class=\"kw-chiffre\"> 50 ans</span> ; <span class=\"kw-etio\">FRCV</span>, ATCD de <span class=\"kw-clinique\">claudication</span></td></tr>\n          <tr><td>Localisation</td><td>Péri-malléolaire, bord régulier</td><td>Zones d'appui / frottement : <span class=\"kw-clinique\">pied</span> (orteil, talon), parfois ulcère « suspendu » à la face antérieure de jambe</td></tr>\n          <tr><td>Douleur</td><td>Peu ou pas douloureux</td><td><span class=\"kw-alerte\">Douloureux ++</span> (souvent intense)</td></tr>\n          <tr><td>Profondeur / fond</td><td>Superficiel, exsudatif, fibrineux</td><td><span class=\"kw-clinique\">Creusant</span> (risque d'exposition tendineuse/osseuse), fond atone et pâle</td></tr>\n          <tr><td><span class=\"kw-bio\">IPS</span></td><td>Normal (0,9 - 1,3)</td><td>Diminué <span class=\"kw-bio\">&lt; 0,9</span> ; mixte si 0,7 - 0,9</td></tr>\n          <tr><td>Peau péri-ulcéreuse</td><td>Dermite ocre, atrophie blanche, <span class=\"kw-clinique\">eczéma</span> variqueux, examen artériel normal</td><td>Peau luisante et dépilée, baisse de température cutanée, <span class=\"kw-clinique\">abolition des pouls</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:16px 0 6px;font-size:14px;\">Diagnostics différentiels de la <span class=\"kw-clinique\">claudication</span></h4>\n      <table >\n        <thead>\n          <tr><th>Origine</th><th>Distance d'apparition</th><th>Douleur / récupération</th><th>Contexte</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Artérielle</strong></td><td>Toujours la même</td><td><span class=\"kw-clinique\">Crampe</span> musculaire obligeant à l'arrêt ; récupération <strong>rapide</strong></td><td>Contexte <span class=\"kw-etio\">athéromateux</span></td></tr>\n          <tr><td><strong>Veineuse</strong></td><td>Variable</td><td>Gonflement douloureux progressif n'obligeant pas à l'arrêt ; récupération lente</td><td>Syndrome post-<span class=\"kw-etio\">thrombotique</span></td></tr>\n          <tr><td><strong>Articulaire</strong></td><td>Dès les premiers pas</td><td>Topographie articulaire, d'emblée maximale ; récupération lente</td><td>Arthrose, rhumatisme <span class=\"kw-etio\">inflammatoire</span></td></tr>\n          <tr><td><strong>Neurologique</strong></td><td>Variable</td><td>Soulagée par l'antéflexion ; topographie radiculaire</td><td><span class=\"kw-etio\">Canal lombaire étroit</span>, arthrose lombaire</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 228 — Ulcère de la jambe</em></p>","frequence":11},{"id":"225-4","rang":"A","rubrique":"Examens complémentaires","titre":"Savoir prescrire les examens complémentaires de première intention","contenu":"<p>L'AOMI est <strong>évoquée cliniquement</strong> puis <strong>confirmée en 1ʳᵉ intention par la mesure des pressions</strong>. Après confirmation, un bilan évalue le handicap fonctionnel, la sévérité hémodynamique et la localisation des lésions.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span class=\"kw-imagerie\">Index de pression systolique</span> (IPS) — examen clé de 1ʳᵉ intention</h4>\n      <p>L'<span class=\"kw-bio\">IPS</span> est le rapport <span class=\"kw-bio\">PAS cheville / PAS bras</span>, mesuré au <span class=\"kw-imagerie\">doppler</span> de poche. La pression de cheville retient la valeur la plus élevée entre artère tibiale postérieure et pédieuse.</p>\n      <table >\n        <thead>\n          <tr><th>Valeur d'<span class=\"kw-imagerie\">IPS</span></th><th>Interprétation</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">1 - 1,40</span></td><td>Valeur normale</td></tr>\n          <tr><td><span class=\"kw-bio\">&lt; 0,90</span></td><td><span class=\"kw-alerte\">AOMI</span> ; également marqueur de risque cardiovasculaire élevé</td></tr>\n          <tr><td><span class=\"kw-chiffre\">&lt; 0,70</span></td><td>AOMI sévère</td></tr>\n          <tr><td><span class=\"kw-chiffre\">&gt; 1,40</span></td><td><span class=\"kw-alerte\">Médiacalcose</span> — rigidité artérielle (calcification de la média, sans rétrécissement intraluminal) ; fréquente chez le diabétique âgé, le dialysé, le grand âge</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Si médiacalcose (<span class=\"kw-imagerie\">IPS</span> &gt; 1,40).</strong> La pression de cheville est ininterprétable : on la remplace par la <span class=\"kw-bio\">pression d'orteil</span> — AOMI si index d'orteil <span class=\"kw-chiffre\">&lt; 0,70</span>, ischémie critique si pression d'orteil <span class=\"kw-alerte\">&lt; 30 mmHg</span>.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Autres examens de 1ʳᵉ intention</h4>\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Apport</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Test de marche</strong> (tapis, protocole de Strandness : 3,2 km/h, pente <span class=\"kw-chiffre\">10 %</span>)</td><td><span class=\"kw-def\">Sensibilise le diagnostic</span> : une baisse de PAS cheville <span class=\"kw-chiffre\">&gt; 30 mmHg</span> et/ou une baisse <span class=\"kw-chiffre\">&gt; 20 % de l'IPS</span> après la marche est évocatrice d'AOMI. Confirme l'origine artérielle de la <span class=\"kw-clinique\">claudication</span>.</td></tr>\n          <tr><td><strong>Écho-<span class=\"kw-imagerie\">Doppler artériel</span></strong></td><td><span class=\"kw-imagerie\">Examen de référence</span> pour localiser les lésions artérielles et leur retentissement hémodynamique ; recherche aussi un AAA.</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">TcPO2</span></strong> (mesure transcutanée de la PO2)</td><td>Utile au diagnostic et à l'évaluation de l'<span class=\"kw-alerte\">ischémie critique</span> (sujet sain &gt;<span class=\"kw-chiffre\"> 50 mmHg</span> ; hypoxie continue <span class=\"kw-chiffre\">10-35 mmHg</span> ; hypoxie critique <span class=\"kw-alerte\">&lt; 10 mmHg</span>).</td></tr>\n          <tr><td><strong>Bilan <span class=\"kw-ttt\">biologique</span> des <span class=\"kw-etio\">FRCV</span></strong></td><td>Recherche d'une <span class=\"kw-bio\">dyslipidémie</span>, d'un <span class=\"kw-bio\">diabète</span>, d'une <span class=\"kw-bio\">insuffisance rénale chronique</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Examens de 2ᵈᵉ intention — uniquement si <span class=\"kw-ttt\">revascularisation</span> envisagée</h4>\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\">Angio-TDM</span></td><td>Imagerie non invasive performante (chenal circulant + paroi). Nécessite un <span class=\"kw-ci\">produit de contraste iodé</span> : vérifier <span class=\"kw-ci\">allergie</span>, fonction rénale, absence de <span class=\"kw-ttt\">biguanides</span>.</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Angio-IRM</span></td><td>Alternative ; le <span class=\"kw-ci\">gadolinium est contre-indiqué si insuffisance rénale sévère</span> (<span class=\"kw-bio\">clairance</span> &lt;<span class=\"kw-chiffre\"> 30 mL</span>/min/1,73 m²). <span class=\"kw-alerte\">Ne visualise pas les calcifications</span>, importantes pour le chirurgien.</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Artériographie</span></td><td><span class=\"kw-ttt\">Ponction</span> artérielle directe + injection de PDC. Surtout réservée aux procédures de <span class=\"kw-ttt\">revascularisation</span> et au réseau jambier/pédieux.</td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/225/angio-arteres-membre-inferieur.png\" alt=\"Angiographie des artères du membre inférieur annotée : iliaque externe, fémorale commune, fémorale profonde et superficielle, poplitée, tibiales, fibulaire\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Angiographie</span> des artères du membre inférieur (examen de 2ᵈᵉ intention) : visualisation simultanée de l'ensemble de l'arbre artériel pour identifier sténoses et occlusions. Source : fiche source EDN item 225.</figcaption>\n      </figure>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — <span class=\"kw-def\">Insuffisance rénale chronique</span></em></p>","frequence":5},{"id":"225-5","rang":"A","rubrique":"Prise en charge","titre":"Connaître le traitement médical : traitement médicamenteux et principes du traitement chirurgical","contenu":"<p>Le traitement de l'AOMI est de <strong>deux ordres</strong> : à <span class=\"kw-def\">visée générale</span> (améliorer le <span class=\"kw-def\">pronostic</span> cardiovasculaire et vital) et à <span class=\"kw-def\">visée locale</span> (résoudre les symptômes et améliorer le pronostic du membre).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Mesures générales</h4>\n      <ul>\n        <li><strong>Prise en charge des <span class=\"kw-etio\">FRCV</span> :</strong> <span class=\"kw-ttt\">arrêt du tabac</span>, contrôle du <span class=\"kw-def\">diabète</span>.</li>\n        <li><strong>Marche / réadaptation supervisée :</strong> <span class=\"kw-ttt\">30-45 minutes, ≥ 3 fois/semaine</span> ; favorise le développement de la circulation collatérale, l'état métabolique musculaire et l'allongement de la distance de marche.</li>\n        <li><strong>Soins de plaies :</strong> sous supervision d'une équipe multidisciplinaire spécialisée.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Traitement <span class=\"kw-etio\">médicamenteux</span></h4>\n      <table >\n        <thead>\n          <tr><th>Classe</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Antiplaquettaire</span> (<span class=\"kw-ttt\">aspirine</span>)</td><td>À dose antiagrégante (indication débattue si AOMI asymptomatique isolée).</td></tr>\n          <tr><td><span class=\"kw-ttt\">Statine</span></td><td>Objectif <span class=\"kw-bio\">LDL &lt; 0,55 g/L</span> et <span class=\"kw-ttt\">réduction</span> <span class=\"kw-chiffre\">≥ 50 %</span> de la valeur initiale ; peut augmenter le <span class=\"kw-clinique\">périmètre de marche</span>.</td></tr>\n          <tr><td><span class=\"kw-ttt\">IEC</span></td><td>Objectif PA <span class=\"kw-chiffre\">&lt; 140/90 mmHg</span> ; intérêt pronostique — instauré <strong>même en l'absence d'<span class=\"kw-def\">HTA</span></strong>.</td></tr>\n          <tr><td><span class=\"kw-ttt\">β-bloquants</span></td><td>Avec <span class=\"kw-ci\">prudence si ischémie critique</span> non revascularisable ; possibles si indication formelle (cardiopathie <span class=\"kw-etio\">ischémique</span>, IC à FE altérée).</td></tr>\n          <tr><td><span class=\"kw-ttt\">Prostaglandines</span></td><td>Proposées en cas d'ischémie critique non revascularisable (perfusions quotidiennes en milieu spécialisé).</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span class=\"kw-ttt\">Revascularisation</span> — indications et principes</h4>\n      <p><strong>Indications :</strong> ischémie permanente ; <span class=\"kw-clinique\">claudication</span> intermittente sévère après traitement médical bien mené <span class=\"kw-chiffre\">&gt; 3-6 mois</span> ; <span class=\"kw-clinique\">périmètre de marche</span> très faible (<span class=\"kw-chiffre\">&lt; 100 m</span>) avec handicap important ; atteintes aorto-iliaques sévères et extensives.</p>\n      <table >\n        <thead>\n          <tr><th>Technique</th><th>Principes</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Endovasculaire</strong></td><td>Meilleurs résultats sur lésions <span class=\"kw-chiffre\">courtes et proximales</span> : <span class=\"kw-ttt\">angioplastie</span> intraluminale par ballonnet ± pose de <span class=\"kw-ttt\">stent</span> ; <span class=\"kw-ttt\">bithérapie antiplaquettaire 1-6 mois</span> selon le geste.</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Chirurgie</span></strong></td><td><span class=\"kw-ttt\">Pontage</span> essentiellement (aorto-bifémoral, fémoro-poplité, fémoro-jambier) ; geste d'<span class=\"kw-ttt\">endartériectomie</span> parfois associé.</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Surveillance</span></strong></td><td>Clinique + <span class=\"kw-imagerie\">écho-<span class=\"kw-imagerie\">Doppler</span></span> — risque de <span class=\"kw-alerte\">thrombose de stent ou de pontage</span> et de dégradation des anastomoses.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Amputation.</strong> Geste ultime, à défaut de toute possibilité de <span class=\"kw-ttt\">revascularisation</span>. Réalisée en <span class=\"kw-clinique\">zone saine et bien oxygénée</span> (intérêt de la <span class=\"kw-imagerie\">TcPO2</span>), en sauvegardant autant que possible l'appui et l'articulation du genou (appareillage par prothèse).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 223 — <span class=\"kw-etio\">Dyslipidémie</span> · 224 — <span class=\"kw-def\">HTA</span></em></p>","frequence":3},{"id":"225-6","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les complications et le pronostic : ischémie aigüe des membres inférieurs, morbimortalité cardiovasculaire","contenu":"<p><strong>Complication aiguë locale</strong> — l'<span class=\"kw-alerte\">ischémie aiguë de membre</span> est la principale complication aiguë : elle peut survenir par thrombose in situ d'une <span class=\"kw-clinique\">lésion</span> d'AOMI préexistante. Tableau, <span class=\"kw-def\">classification</span> et traitement sont détaillés dans les objectifs <em>« <span class=\"kw-def\">Diagnostic positif</span> »</em> et <em>« Identifier une <span class=\"kw-alerte\">urgence</span> »</em> de l'<span class=\"kw-alerte\">ischémie aiguë</span>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Morbimortalité cardiovasculaire</h4>\n      <p>L'AOMI est l'<span class=\"kw-def\">expression locale d'une maladie systémique</span> : le <span class=\"kw-alerte\">pronostic vital</span> est avant tout conditionné par les atteintes <span class=\"kw-alerte\">coronariennes</span> et <span class=\"kw-alerte\">cérébrovasculaires</span> associées, qui doivent être recherchées et orientées par la clinique. Un <span class=\"kw-bio\">IPS &lt; 0,90</span> est associé à un risque cardiovasculaire élevé (accident coronarien ou cérébral fatal ou non) — l'<span class=\"kw-imagerie\">IPS</span> est utilisé comme <span class=\"kw-def\">marqueur de risque cardiovasculaire</span>.</p>\n      <table >\n        <thead>\n          <tr><th>Situation</th><th><span class=\"kw-def\">Pronostic</span></th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Claudication</span> intermittente</td><td>Espérance de vie réduite de <span class=\"kw-chiffre\">-10 ans</span></td></tr>\n          <tr><td>Ischémie d'effort</td><td><span class=\"kw-def\">Mortalité</span> <span class=\"kw-alerte\">15 % à 5 ans</span></td></tr>\n          <tr><td>Ischémie permanente chronique</td><td><span class=\"kw-def\">Mortalité</span> <span class=\"kw-alerte\">25 % à 1 an</span> et <span class=\"kw-alerte\">70 % à 5 ans</span></td></tr>\n          <tr><td>Risque d'amputation du membre inférieur</td><td><span class=\"kw-alerte\">≈ 5 % à 5 ans</span>, notamment si mauvais contrôle des <span class=\"kw-etio\">FRCV</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 340 — <span class=\"kw-def\">AVC</span></em></p>","frequence":1},{"id":"225-7","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir définir et identifier les manifestations cliniques d’ischémie aiguë complète ou incomplète","contenu":"<p>L'<span class=\"kw-def\">ischémie aiguë</span> correspond à une <strong>interruption brutale du flux artériel</strong> d'un membre entraînant une ischémie tissulaire, pouvant aboutir à une <span class=\"kw-clinique\">nécrose</span>. C'est une <span class=\"kw-alerte\">urgence absolue</span> : tout retard expose au risque d'amputation, voire de décès.</p>\n      <div class=\"callout callout-danger\">\n        <strong>Chronologie de la souffrance tissulaire.</strong> Cellules nerveuses : <span class=\"kw-alerte\">&lt; 2 h</span>. Cellules musculaires : <span class=\"kw-alerte\">6-8 h</span> (rhabdomyolyse, risque de <span class=\"kw-alerte\">syndrome des loges</span>). <span class=\"kw-clinique\">Nécrose</span> cutanée : à partir de <span class=\"kw-alerte\">24 h</span>.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span class=\"kw-def\">Classification</span> de Rutherford</h4>\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-def\">Grade</span></th><th><span class=\"kw-clinique\">Déficit sensitif</span></th><th><span class=\"kw-clinique\">Déficit moteur</span></th><th><span class=\"kw-def\">Pronostic</span></th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>I</strong> — viable</td><td>Absent</td><td>Absent</td><td>Pas de <span class=\"kw-alerte\">menace</span> immédiate, <span class=\"kw-alerte\">urgence</span> relative</td></tr>\n          <tr><td><strong>IIa</strong> — discrètement menaçante</td><td>Absent ou limité aux orteils</td><td>Absent</td><td>Récupérable si prise en charge</td></tr>\n          <tr><td><strong>IIb</strong> — immédiatement menaçante</td><td>Présent au-delà des orteils</td><td>Modéré</td><td>Récupération possible si PEC immédiate</td></tr>\n          <tr><td><strong>III</strong> — irréversible</td><td>Anesthésie importante</td><td>Important, <span class=\"kw-alerte\">paralysie</span></td><td>Perte tissulaire et déficit séquellaire inévitables</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Tableau clinique</h4>\n      <ul>\n        <li><strong>Signes fonctionnels :</strong> <span class=\"kw-clinique\">douleur spontanée brutale</span> à type de <span class=\"kw-clinique\">broiement</span>, impotence fonctionnelle du membre.</li>\n        <li><strong>Signes physiques :</strong> membre <span class=\"kw-clinique\">froid, pâle, livide</span> ; <span class=\"kw-clinique\">abolition des pouls en aval</span> de l'occlusion (estime la topographie).</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong>Ischémie complète <span class=\"kw-bio\">vs</span> incomplète — point clé.</strong> La <span class=\"kw-alerte\">paralysie signe l'ischémie complète</span> (gravité majeure) : impossibilité de mobiliser les orteils, de relever le pied (nerf fibulaire commun). <strong>Son absence définit l'ischémie incomplète.</strong> Autres <span class=\"kw-alerte\">signes de gravité</span> : douleur à la palpation des masses musculaires, hypoesthésie évoluant vers l'anesthésie cutanée. <span class=\"kw-alerte\">Ischémie dépassée</span> (amputation d'emblée) : <span class=\"kw-alerte\">rigidité musculaire</span>, <span class=\"kw-alerte\">marbrures</span>, <span class=\"kw-alerte\">phlyctènes</span>.\n      </div>\n      <p>Dans le cas le plus grave, l'<span class=\"kw-alerte\">occlusion de la bifurcation aortique</span> entraîne une ischémie bilatérale sévère avec paralysie sensitivomotrice et signes généraux au premier plan (collapsus cardiovasculaire).</p>\n      <p><strong>Paraclinique</strong> — le <span class=\"kw-def\">diagnostic est clinique</span> ; les examens ne doivent pas retarder la <span class=\"kw-ttt\">revascularisation</span>. <span class=\"kw-imagerie\">ECG</span> systématique à visée étiologique ; <span class=\"kw-imagerie\">écho-<span class=\"kw-imagerie\">Doppler</span></span> possible sans perte de temps si <span class=\"kw-def\">grade</span> I sans atteinte neurologique ; <span class=\"kw-imagerie\">artériographie</span> le plus souvent réalisée au bloc opératoire.</p>","frequence":4},{"id":"225-8","rang":"B","rubrique":"Etiologies","titre":"Connaître les autres causes de l’ischémie aiguë","contenu":"<p>Deux grands mécanismes sont à distinguer : la <span class=\"kw-etio\">thrombose artérielle in situ</span> et l'<span class=\"kw-etio\">embolie sur artères saines</span>.</p>\n      <table >\n        <thead>\n          <tr><th></th><th>Thrombose artérielle in situ</th><th>Embolie sur artères saines</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Terrain</span></td><td>Sujet âgé à <span class=\"kw-etio\">FRCV</span> (voire AOMI préexistante)</td><td>Sujet jeune sans ATCD vasculaire, mais pouvant avoir une cardiopathie</td></tr>\n          <tr><td>Douleur</td><td>Intensité moyenne, survenue progressive (collatéralité préexistante)</td><td><span class=\"kw-clinique\">Très brutale, aiguë et sévère</span> (absence de collatérales) ; peut suivre des <span class=\"kw-clinique\">palpitations</span></td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Étiologies de la thrombose in situ</h4>\n      <ul>\n        <li><strong>Sur artères pathologiques :</strong> <span class=\"kw-etio\">AOMI</span> ++++ ; artériopathies non athéromateuses ; anévrisme poplité thrombosé ; <span class=\"kw-etio\">dissection</span> aorto-iliaque.</li>\n        <li><strong>Sur artères saines :</strong> <span class=\"kw-clinique\">déshydratation</span> / hémoconcentration ; kyste adventiciel ; thrombophlébite <span class=\"kw-etio\">ischémique</span> ; <span class=\"kw-etio\">coagulopathies</span> et thrombophilies ; <span class=\"kw-etio\">thrombopénie induite par l'héparine</span> ; <span class=\"kw-etio\">SAPL</span>.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Étiologies de l'embolie</h4>\n      <ul>\n        <li><strong>Causes cardiaques :</strong> <span class=\"kw-etio\">fibrillation atriale</span> +++ ; valvulopathies ; foramen ovale perméable, anévrisme du septum interatrial ; <span class=\"kw-etio\">IDM</span>, dyskinésie ou anévrisme du VG ; tumeurs cardiaques (myxome de l'atrium).</li>\n        <li><strong>Atteintes aortiques :</strong> <span class=\"kw-etio\">athérome</span>, anévrisme, aortite, tumeurs aortiques.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Nuance.</strong> Ces deux tableaux ne sont pas toujours distincts : une embolie peut survenir sur des artères déjà atteintes par l'AOMI, et une thrombose in situ peut survenir sur la <span class=\"kw-alerte\">rupture</span> d'une <span class=\"kw-clinique\">plaque</span> initialement non occlusive, sans signe préalable d'AOMI.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 232 — <span class=\"kw-def\">Fibrillation atriale</span></em></p>","frequence":0},{"id":"225-9","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les principes d’un traitement en urgence","contenu":"<p>La prise en charge de l'<span class=\"kw-alerte\">ischémie aiguë</span> de membre est une <span class=\"kw-alerte\">urgence absolue</span> : la <span class=\"kw-ttt\">revascularisation</span> doit être effectuée <strong>dans les <span class=\"kw-chiffre\">6 heures</span></strong> qui suivent le début du tableau.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Traitement médical immédiat</h4>\n      <ul>\n        <li><strong>Anticoagulation :</strong> <span class=\"kw-ttt\">héparine non fractionnée</span> (bolus puis perfusion continue, <span class=\"kw-bio\">TCA cible 2-3</span>) dès le diagnostic, après bilan de coagulation.</li>\n        <li><strong>Antalgie :</strong> <span class=\"kw-ttt\">antalgiques</span> de niveau 3 souvent nécessaires d'emblée.</li>\n        <li><strong>Mesures associées :</strong> <span class=\"kw-ttt\">oxygénothérapie</span> nasale ; équilibration hémodynamique (remplissage) si besoin.</li>\n        <li><strong>Soins locaux / nursing :</strong> éviter tout point de compression (protection mousse/coton, position légèrement déclive), proscrire frottements et adhésifs sur la peau <span class=\"kw-etio\">ischémique</span>.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span class=\"kw-ttt\">Revascularisation</span> (&lt;<span class=\"kw-chiffre\"> 6 h</span>)</h4>\n      <table >\n        <thead>\n          <tr><th>Mécanisme</th><th>Technique</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Embolie sur artères saines</td><td><span class=\"kw-ttt\">Embolectomie par sonde de Fogarty</span> sous contrôle angiographique</td></tr>\n          <tr><td>Thrombose sur artère pathologique</td><td>Techniques conventionnelles (endartériectomie, <span class=\"kw-ttt\">pontage</span>) ou endovasculaires (recanalisation, angioplastie, thrombo-aspiration)</td></tr>\n          <tr><td><span class=\"kw-ttt\">Thrombolyse</span> in situ</td><td><span class=\"kw-ci\">Contre-indiquée si ischémie sensitivo-motrice</span> (délai d'action trop long, caillot volumineux)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Aponévrotomie jambière</strong> — en cas de syndrome des loges, ou discutée systématiquement si <span class=\"kw-ttt\">revascularisation</span> tardive. <strong>Amputation</strong> — d'emblée si ischémie dépassée, ou secondairement.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/225/algorithme-ischemie-aigue.png\" alt=\"Algorithme de prise en charge de l'ischémie aiguë de membre selon le grade : viable (grade I), viable avec déficit sensitif (grade II), irréversible (grade III)\" loading=\"lazy\">\n        <figcaption>Algorithme de prise en charge de l'<span class=\"kw-alerte\">ischémie aiguë</span> de membre : <span class=\"kw-ttt\">héparine</span> + <span class=\"kw-ttt\">antalgiques</span> d'emblée, puis orientation selon le <span class=\"kw-def\">grade</span> — imagerie ou revascularisation en <span class=\"kw-alerte\">urgence</span> (I-II), amputation (III). Source : fiche source EDN item 225.</figcaption>\n      </figure>\n\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-clinique\">Syndrome de revascularisation</span>.</strong> À la remise en circulation, le relargage de métabolites des cellules lysées provoque : <span class=\"kw-bio\">hyperkaliémie</span>, hyperuricémie, hyperphosphorémie, <span class=\"kw-bio\">acidose métabolique</span>, <span class=\"kw-bio\">hypocalcémie</span>, myoglobinémie / myoglobinurie, <span class=\"kw-alerte\">CIVD</span>, <span class=\"kw-alerte\">insuffisance rénale aiguë</span> par <span class=\"kw-clinique\">nécrose</span> tubulaire aiguë. Traitement : <span class=\"kw-def\">surveillance</span> (diurèse, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">urée</span>, <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">CPK</span>) ; <span class=\"kw-ttt\">alcalinisation</span> (<span class=\"kw-bio\">bicarbonates</span> IV) de l'acidose ; <span class=\"kw-ttt\">chélateur de potassium</span> de l'hyperkaliémie ; voire dialyse et lavage de membre.\n      </div>\n      <p><strong>Au long cours</strong> — après <span class=\"kw-ttt\">revascularisation</span> : bilan étiologique (cardiaque : <span class=\"kw-imagerie\">Holter</span>, <span class=\"kw-imagerie\">ETT</span> ± <span class=\"kw-imagerie\">ETO</span> ; artériel : <span class=\"kw-imagerie\">écho-<span class=\"kw-imagerie\">Doppler</span></span>) et traitement de la cause (<span class=\"kw-ttt\">anticoagulation</span> au long cours si FA, <span class=\"kw-ttt\">antiagrégant</span> + contrôle des <span class=\"kw-etio\">FRCV</span> si origine <span class=\"kw-etio\">thrombotique</span>).</p>","frequence":1},{"id":"225-10","rang":"A","rubrique":"Définition","titre":"Connaître la définition et l’histoire naturelle d’un anévrisme de l’aorte abdominale et savoir rechercher d’autres localisations anévrismales","contenu":"<p>Un <span class=\"kw-def\">anévrisme artériel</span> est une <strong>dilatation focale et permanente</strong> d'une artère, avec perte du parallélisme de ses parois, dont le <span class=\"kw-clinique\">diamètre</span> est <span class=\"kw-chiffre\">&gt; 1,5 ×</span> le diamètre d'amont. La dilatation peut être <span class=\"kw-clinique\">fusiforme</span> ou <span class=\"kw-clinique\">sacciforme</span>. Diamètre normal de l'aorte abdominale : <span class=\"kw-chiffre\">18-20 mm</span> chez l'homme, <span class=\"kw-chiffre\">14-16 mm</span> chez la femme.</p>\n      <div class=\"callout callout-info\">\n        <strong>Définition <span class=\"kw-def\">HAS</span> de l'AAA.</strong> Soit un <span class=\"kw-clinique\">diamètre</span> antéro-postérieur <span class=\"kw-chiffre\">&gt; 30 mm</span>, soit une dilatation <span class=\"kw-chiffre\">≥ + 50 %</span> par rapport au diamètre de l'aorte abdominale sus-jacente normale.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Histoire naturelle — croissance et risque évolutif</h4>\n      <ul>\n        <li><strong>Croissance :</strong> en moyenne <span class=\"kw-chiffre\">2-4 mm/an</span> ; <span class=\"kw-alerte\">non linéaire</span> chez un même patient et variable d'un patient à l'autre ; d'autant <strong>plus rapide que le <span class=\"kw-clinique\">diamètre</span> est grand</strong>. AAA dit « à croissance rapide » si <span class=\"kw-alerte\">&gt; 1 cm/an</span> (indication chirurgicale).</li>\n        <li><strong>Risque évolutif = la <span class=\"kw-alerte\">rupture</span></strong> ; ce risque augmente avec le <span class=\"kw-clinique\">diamètre</span> : <span class=\"kw-chiffre\">&lt; 0,5 %/an</span> si diamètre &lt;<span class=\"kw-chiffre\"> 40 mm</span>, puis croissant. Le risque est <span class=\"kw-alerte\">majoré chez la femme à diamètre égal</span> (× 4).</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Localisations — rechercher d'autres anévrismes</h4>\n      <p>L'aorte abdominale est la localisation la plus fréquente, surtout dans le segment <span class=\"kw-clinique\">sous-rénal</span>. La découverte d'un AAA justifie la recherche systématique d'autres localisations :</p>\n      <table >\n        <thead>\n          <tr><th>Localisation à rechercher</th><th>Modalité</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Anévrisme poplité — associé dans <span class=\"kw-chiffre\">30 %</span> des cas</td><td><span class=\"kw-imagerie\">Écho-<span class=\"kw-imagerie\">Doppler</span></span> des artères des membres inférieurs</td></tr>\n          <tr><td>Anévrisme des artères iliaques</td><td><span class=\"kw-imagerie\">Écho-<span class=\"kw-imagerie\">Doppler</span></span> ou <span class=\"kw-imagerie\">angio-<span class=\"kw-imagerie\">TDM</span></span></td></tr>\n          <tr><td>Anévrisme de l'aorte thoracique</td><td><span class=\"kw-imagerie\">Angio-<span class=\"kw-imagerie\">TDM</span></span> thoraco-abdomino-pelvienne</td></tr>\n          <tr><td><span class=\"kw-def\">Dépistage</span> de l'<span class=\"kw-etio\">athérosclérose</span></td><td>En particulier <span class=\"kw-clinique\">coronaires</span> et <span class=\"kw-clinique\">troncs supra-aortiques</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"225-11","rang":"B","rubrique":"Etiologies","titre":"Connaître les principales étiologies des anévrismes de l’aorte abdominale et les principes du dépistage","contenu":"<p><strong><span class=\"kw-def\">Facteurs de risque</span> principaux</strong> de l'AAA : <span class=\"kw-clinique\">tabagisme</span>, âge avancé, <span class=\"kw-clinique\">sexe masculin</span>, ATCD familiaux d'AAA.</p>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Les diabétiques sont <span class=\"kw-alerte\">moins souvent atteints</span> d'AAA — le <span class=\"kw-def\">diabète</span> est un <strong>facteur protecteur</strong> (via la médiacalcose). C'est l'inverse de l'AOMI, où le <span class=\"kw-def\">diabète</span> est un FR dominant.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Étiologies</h4>\n      <table >\n        <thead>\n          <tr><th>Étiologie</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Athéromateuse</span></td><td>AAA associé à des lésions athéromateuses d'autres sites dans <span class=\"kw-chiffre\">80-90 %</span> des cas.</td></tr>\n          <tr><td><span class=\"kw-etio\">Maladies des tissus élastiques</span></td><td>Maladie de <span class=\"kw-etio\">Marfan</span>, d'<span class=\"kw-etio\">Ehlers-Danlos</span>, syndrome de <span class=\"kw-etio\">Loeys-Dietz</span>.</td></tr>\n          <tr><td><span class=\"kw-etio\">Aortites</span></td><td>Maladie de <span class=\"kw-etio\">Takayasu</span>, <span class=\"kw-etio\">Behçet</span>, <span class=\"kw-etio\">Horton</span>, <span class=\"kw-etio\">syphilis</span>.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Évolution</span> d'une <span class=\"kw-etio\">dissection</span></td><td><span class=\"kw-clinique\">Évolution</span> anévrismale d'une <span class=\"kw-alerte\"><span class=\"kw-etio\">dissection</span> aortique</span>.</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-def\">Physiopathologie</span></strong> — les caractéristiques histologiques diffèrent de l'<span class=\"kw-etio\">athérosclérose</span> : suractivité d'enzymes détruisant la matrice collagénique (<span class=\"kw-def\">métalloprotéases</span>), destruction des fibres élastiques et fragmentation du collagène, altération de la média qui perd sa capacité à lutter contre la distension.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span class=\"kw-def\">Dépistage</span> — <span class=\"kw-imagerie\">écho-<span class=\"kw-imagerie\">Doppler</span></span> de l'aorte abdominale</h4>\n      <ul>\n        <li>Tous les <span class=\"kw-clinique\">artériopathes</span>.</li>\n        <li><strong>Hommes</strong> âgés de <span class=\"kw-chiffre\">60-85 ans</span>.</li>\n        <li><strong>Femmes</strong> hypertendues ou tabagiques âgées de <span class=\"kw-chiffre\">60-85 ans</span>.</li>\n        <li>Hommes et femmes de <span class=\"kw-chiffre\">&gt; 50 ans</span> avec ATCD familial d'anévrisme aortique chez un apparenté du 1ᵉʳ degré.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 221 — <span class=\"kw-etio\">Athérome</span></em></p>","frequence":2},{"id":"225-12","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques des anévrismes de l’aorte","contenu":"<h4 style=\"margin:4px 0 6px;font-size:14px;\">Forme asymptomatique (la plus fréquente)</h4>\n      <p>Découverte le plus souvent <strong>fortuite</strong> : <span class=\"kw-clinique\">masse abdominale battante et expansive</span> de la région para-ombilicale, avec ou sans souffle (palpable surtout chez les sujets maigres ou si l'anévrisme est volumineux), ou découverte d'imagerie (<span class=\"kw-imagerie\">échographie</span>, <span class=\"kw-imagerie\">TDM</span>, <span class=\"kw-imagerie\">IRM</span>).</p>\n      <div class=\"callout callout-info\">\n        <strong>Signe de Bakey.</strong> Possibilité de glisser la main entre le pôle supérieur de l'anévrisme et les côtes du patient — en faveur d'un anévrisme <span class=\"kw-clinique\">sous-rénal</span>.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Formes symptomatiques (complications)</h4>\n      <table >\n        <thead>\n          <tr><th>Complication</th><th>Traduction clinique</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Fissuration / rupture</span></td><td><span class=\"kw-clinique\">Douleur abdominale</span> ou lombaire ± tableau de <span class=\"kw-alerte\">choc hémorragique</span> ; <span class=\"kw-alerte\">rupture</span> rétropéritonéale (syndrome fissuraire) ou intrapéritonéale (foudroyante).</td></tr>\n          <tr><td>Fistules</td><td><strong><span class=\"kw-clinique\">Fistule</span> aorto-cave :</strong> <span class=\"kw-def\">insuffisance cardiaque</span> à débit élevé.<br><strong>Fistule aorto-digestive :</strong> hémorragie digestive (<span class=\"kw-clinique\">hématémèse</span>, <span class=\"kw-clinique\">rectorragie</span>).</td></tr>\n          <tr><td>Complication <span class=\"kw-etio\">embolique</span></td><td>À partir du <span class=\"kw-etio\">thrombus</span> intra-anévrismal : occlusion artérielle aiguë du membre inférieur, embolies de cristaux de <span class=\"kw-bio\">cholestérol</span> (<span class=\"kw-clinique\">orteil bleu</span>).</td></tr>\n          <tr><td>Compression d'organes</td><td><strong>Duodénum :</strong> <span class=\"kw-clinique\">vomissements</span> post-prandiaux ; <strong>nerfs :</strong> radiculalgies ; <strong>VCI :</strong> <span class=\"kw-clinique\">œdèmes</span> des MI ; <strong>os :</strong> érosions vertébrales ; <strong>voies urinaires :</strong> coliques néphrétiques.</td></tr>\n          <tr><td>Anévrisme <span class=\"kw-etio\">inflammatoire</span></td><td>Gangue <span class=\"kw-etio\">inflammatoire</span> péri-anévrismale : <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">AEG</span>, <span class=\"kw-bio\">syndrome inflammatoire</span> <span class=\"kw-ttt\">biologique</span> (<span class=\"kw-bio\">VS</span>, <span class=\"kw-bio\">CRP</span>).</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"225-13","rang":"A","rubrique":"Examens complémentaires","titre":"Savoir comment faire le diagnostic des anévrysmes de l’aorte abdominale","contenu":"<table >\n        <thead>\n          <tr><th>Examen</th><th>Place et apport</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\">Échographie abdominale</span></td><td>Examen de <strong><span class=\"kw-def\">dépistage</span></strong> et de <strong><span class=\"kw-def\">suivi</span></strong> des AAA asymptomatiques : donne le <span class=\"kw-clinique\">diamètre</span> maximal et permet la <span class=\"kw-def\">surveillance</span> de la croissance ; <span class=\"kw-imagerie\">échographie</span> annuelle après <span class=\"kw-ttt\">chirurgie</span> conventionnelle.</td></tr>\n          <tr><td><span class=\"kw-imagerie\">TDM thoraco-abdomino-pelvienne injectée</span></td><td><strong>Examen pré-thérapeutique de référence.</strong> Indiquée <span class=\"kw-alerte\">en urgence en cas d'AAA douloureux ou de suspicion de rupture</span>. Précise les diamètres et l'extension par rapport aux artères rénales et iliaques.</td></tr>\n          <tr><td><span class=\"kw-imagerie\">IRM</span></td><td>Peut remplacer l'<span class=\"kw-imagerie\">angio-<span class=\"kw-imagerie\">TDM</span></span> en cas de <span class=\"kw-ci\">contre-indication</span>.</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Artériographie</span></td><td>N'a <strong>plus d'indication diagnostique</strong> : ne révèle que la lumière artérielle, mesure non fiable du <span class=\"kw-clinique\">diamètre</span> à cause du <span class=\"kw-etio\">thrombus</span> mural fréquent.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège <span class=\"kw-imagerie\">TDM</span>.</strong> La longueur de l'AAA et la présence d'un <span class=\"kw-etio\">thrombus</span> endoluminal <span class=\"kw-alerte\">ne modifient pas la prise en charge</span> — seul le <span class=\"kw-clinique\">diamètre</span> maximal compte.\n      </div>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/225/tdm-aaa-coupe-axiale.png\" alt=\"TDM abdominale en coupe axiale montrant un anévrisme de l'aorte abdominale sous-rénale\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">TDM</span> abdominale, coupe axiale : anévrisme de l'aorte abdominale sous-rénale — dilatation focale de l'aorte. Source : fiche source EDN item 225.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/225/tdm-aaa-thrombus.png\" alt=\"TDM abdominale d'un anévrisme de l'aorte abdominale avec thrombus mural périphérique et chenal circulant central\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">TDM</span> abdominale : AAA avec thrombus mural périphérique (hypodense) et chenal circulant central rehaussé après injection. Source : fiche source EDN item 225.</figcaption>\n      </figure>\n      <p><strong>Bilan associé</strong> — la découverte d'un AAA justifie la recherche d'un anévrisme poplité (associé dans <span class=\"kw-chiffre\">30 %</span> des cas), des artères iliaques, de l'aorte thoracique, et le <span class=\"kw-def\">dépistage</span> des coronaires et des troncs supra-aortiques.</p>","frequence":1},{"id":"225-14","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes thérapeutiques d’un anévrisme de l’aorte abdominale","contenu":"<p><strong>Aucun médicament</strong> ne permet de limiter la croissance, de faire régresser le <span class=\"kw-clinique\">diamètre</span> ou de prévenir la <span class=\"kw-alerte\">rupture</span> d'un AAA.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Mesures générales et traitement médical</h4>\n      <ul>\n        <li><span class=\"kw-ttt\">Arrêt du tabac</span> (le <span class=\"kw-etio\">tabac</span> favorise la croissance et la <span class=\"kw-alerte\">rupture</span>).</li>\n        <li>Contrôle des <span class=\"kw-etio\">FRCV</span> ; recherche d'un AAA chez les apparentés du 1ᵉʳ degré de <span class=\"kw-chiffre\">&gt; 50 ans</span>.</li>\n        <li>En raison des FR communs avec l'<span class=\"kw-etio\">athérosclérose</span> : <span class=\"kw-ttt\">statines</span>, <span class=\"kw-ttt\">antiplaquettaire</span>, <span class=\"kw-ttt\">IEC / ARA2</span>.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Conduite à tenir selon le <span class=\"kw-clinique\">diamètre</span></h4>\n      <table >\n        <thead>\n          <tr><th>Diamètre</th><th>Conduite à tenir</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">&lt; 40 mm</span></td><td><span class=\"kw-imagerie\">Échographie</span> de <span class=\"kw-def\">surveillance</span> <strong>1×/an</strong></td></tr>\n          <tr><td><span class=\"kw-chiffre\">40-49 mm</span></td><td><span class=\"kw-imagerie\">Échographie</span> de <span class=\"kw-def\">surveillance</span> <strong>tous les <span class=\"kw-chiffre\">6 mois</span></strong></td></tr>\n          <tr><td><span class=\"kw-chiffre\">≥ 50 mm</span></td><td><span class=\"kw-ttt\">Chirurgie</span> discutée chez l'homme (voire avant <span class=\"kw-chiffre\">50 mm</span> chez la femme)</td></tr>\n          <tr><td>Croissance <span class=\"kw-alerte\">&gt; 1 cm/an</span> ou anévrisme compliqué</td><td>Traitement chirurgical indiqué</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Seuil chirurgical — balance risque opératoire / risque de <span class=\"kw-alerte\">rupture</span></h4>\n      <p>L'indication chirurgicale repose sur le <strong>croisement du risque opératoire et du risque de <span class=\"kw-alerte\">rupture</span> spontanée</strong>, qui s'inversent autour de <span class=\"kw-chiffre\">50-55 mm</span> : on opère quand le risque de rupture dépasse le risque opératoire.</p>\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-clinique\">Diamètre</span></th><th>Balance des risques</th><th>Décision</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">&lt; 50 mm</span></td><td>Risque opératoire <strong>&gt;</strong> risque de <span class=\"kw-alerte\">rupture</span></td><td><strong><span class=\"kw-def\">Surveillance</span></strong> (<span class=\"kw-imagerie\">écho-<span class=\"kw-imagerie\">Doppler</span></span>)</td></tr>\n          <tr><td><span class=\"kw-chiffre\">50-55 mm</span></td><td>Zone de décision (selon <span class=\"kw-def\">terrain</span>)</td><td><span class=\"kw-ttt\">Chirurgie</span> selon le <span class=\"kw-def\">terrain</span>, croissance <span class=\"kw-alerte\">&gt; 1 cm/an</span> ou symptômes</td></tr>\n          <tr><td><span class=\"kw-chiffre\">&gt; 55 mm</span></td><td>Risque de <span class=\"kw-alerte\">rupture</span> <strong>&gt;</strong> risque opératoire</td><td><strong><span class=\"kw-ttt\">Chirurgie</span></strong> : <span class=\"kw-ttt\">mise à plat-greffe</span> ou <span class=\"kw-ttt\">endoprothèse</span> (<span class=\"kw-ttt\">EVAR</span>)</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span class=\"kw-ttt\">Chirurgie</span> — principe et techniques</h4>\n      <p><strong>Principe :</strong> exclure la zone anévrismale du flux circulatoire par interposition d'une prothèse vasculaire. Le choix entre les deux techniques dépend du <span class=\"kw-def\">terrain</span> et de l'anatomie.</p>\n      <table >\n        <thead>\n          <tr><th>Technique</th><th>Principes et <span class=\"kw-def\">surveillance</span></th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-ttt\">Chirurgie</span> conventionnelle</strong> (<span class=\"kw-ttt\">mise à plat-greffe</span>)</td><td>Laparotomie, clampage aortique, ablation du <span class=\"kw-etio\">thrombus</span>, tube prothétique suturé à l'aorte saine. Risque d'<span class=\"kw-alerte\">anévrisme anastomotique</span> → <span class=\"kw-def\">surveillance</span> annuelle par <span class=\"kw-imagerie\">écho-<span class=\"kw-imagerie\">Doppler</span></span>.</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Chirurgie</span> endovasculaire</strong> (<span class=\"kw-ttt\">endoprothèse</span>)</td><td>Moins invasive ; <span class=\"kw-ttt\">endoprothèse</span> introduite par voie fémorale, étanchéité sur l'aorte saine et les iliaques. Privilégiée si risque opératoire élevé. Risques : <span class=\"kw-alerte\">endofuite</span>, migration, plicature de jambage → <span class=\"kw-def\">surveillance</span> au long cours par <span class=\"kw-imagerie\">écho-<span class=\"kw-imagerie\">Doppler</span></span> ou <span class=\"kw-imagerie\">angio-<span class=\"kw-imagerie\">TDM</span></span>.</td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"225-15","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir reconnaître et prendre en charge une situation d’urgence chez les patient porteur d’un anévrisme de l’aorte abdominale","contenu":"<div class=\"callout callout-danger\">\n        <strong>AAA rompu — <span class=\"kw-alerte\">urgence</span> extrême.</strong> Taux de <span class=\"kw-def\">mortalité</span> globale <span class=\"kw-alerte\">&gt; 80 %</span>. Orientation immédiate vers un centre spécialisé de <span class=\"kw-ttt\">chirurgie</span> vasculaire. Une <span class=\"kw-imagerie\">TDM</span> peut être réalisée si l'état hémodynamique le permet — mais <strong>aucune imagerie ne doit retarder l'intervention chez un patient en <span class=\"kw-alerte\">choc</span> <span class=\"kw-etio\">hémorragique</span></strong>. Si les mesures de <span class=\"kw-alerte\">réanimation</span> ne stabilisent pas le patient : passage direct au bloc.\n      </div>\n      <table >\n        <thead>\n          <tr><th>Situation d'urgence</th><th>Conduite à tenir</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">AAA douloureux</span></td><td><span class=\"kw-imagerie\">TDM</span> en <span class=\"kw-alerte\">urgence</span> + prise en charge de l'état général, cardiovasculaire, rénal et respiratoire ; <span class=\"kw-alerte\">hospitalisation</span> rapide pour intervention.</td></tr>\n          <tr><td>Ischémie aiguë du membre inférieur</td><td>Ischémie par embolie à partir du <span class=\"kw-etio\">thrombus</span> de l'AAA : prise en charge spécifique immédiate par <span class=\"kw-ttt\">embolectomie</span> ; l'AAA est traité secondairement.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Fistule</span> aorto-cave</td><td><span class=\"kw-clinique\">Insuffisance cardiaque à débit élevé</span> (<span class=\"kw-alerte\">défaillance</span> hémodynamique sans déglobulisation) → urgence absolue en <span class=\"kw-ttt\">chirurgie</span> vasculaire.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Fistule</span> aorto-digestive</td><td><span class=\"kw-clinique\">Hémorragie digestive</span> (<span class=\"kw-clinique\">hématémèse</span> ou <span class=\"kw-clinique\">rectorragie</span>) avec <span class=\"kw-alerte\">défaillance</span> hémodynamique → urgence absolue en <span class=\"kw-ttt\">chirurgie</span> vasculaire.</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":4},{"id":"225-16","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’ischémie intestinale aiguë et chronique","contenu":"<p>La vascularisation artérielle du tube digestif repose sur <strong>3 axes</strong>. Le risque d'ischémie d'un organe dépend de la richesse de ses suppléances anastomotiques — la vascularisation du <span class=\"kw-alerte\">grêle est terminale</span>, d'où un risque élevé.</p>\n      <table >\n        <thead>\n          <tr><th>Axe artériel</th><th>Territoire vascularisé</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Tronc cœliaque</span></td><td>Branches hépatique commune, splénique, gastrique gauche → estomac, foie, rate</td></tr>\n          <tr><td><span class=\"kw-def\">Artère mésentérique supérieure</span> (AMS)</td><td>Jéjunum, iléon, cæcum, côlon droit, 1/3 droit du côlon transverse</td></tr>\n          <tr><td><span class=\"kw-def\">Artère mésentérique inférieure</span> (AMI)</td><td>2/<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> g</span>auches du côlon transverse, côlon gauche, sigmoïde, haut rectum</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Arcades anastomotiques</strong> — l'arcade de <span class=\"kw-def\">Rio Branco</span> (arcades pancréatico-duodénales) relie le tronc cœliaque à l'AMS ; l'arcade de <span class=\"kw-def\">Riolan</span> relie l'AMS à l'AMI. Ces communications, peu développées à l'état normal, peuvent compenser des obstructions <strong>progressives</strong> mais sont inefficaces en cas d'obstruction <strong>aiguë</strong>.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/225/vascularisation-digestive.png\" alt=\"Schéma de la vascularisation artérielle de l'appareil digestif abdominal : tronc cœliaque, artère mésentérique supérieure, artère mésentérique inférieure\" loading=\"lazy\">\n        <figcaption>Vascularisation artérielle de l'appareil digestif abdominal — les 3 axes : tronc cœliaque, artère mésentérique supérieure et inférieure. Source : fiche source EDN item 225.</figcaption>\n      </figure>\n      <table >\n        <thead>\n          <tr><th>Entité</th><th>Définition</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Ischémie intestinale chronique</span></td><td>Sténoses artérielles progressives (<span class=\"kw-etio\">artérite athéromateuse</span> dans <span class=\"kw-chiffre\">95 %</span> des cas) ; <strong>2 des 3 axes doivent être touchés</strong> pour devenir symptomatique ; l'hypoperfusion post-prandiale entraîne des douleurs.</td></tr>\n          <tr><td><span class=\"kw-def\">Ischémie intestinale aiguë</span> / <span class=\"kw-etio\">infarctus mésentérique</span></td><td>Interruption brutale de la vascularisation par occlusion artérielle (thrombose in situ, embolie, <span class=\"kw-etio\">dissection</span>). La muqueuse souffre en premier ; lésions <span class=\"kw-alerte\">irréversibles dès 4 h</span> (<span class=\"kw-clinique\">nécrose</span> transpariétale → <span class=\"kw-etio\">infarctus mésentérique</span>, risque de perforation et de <span class=\"kw-etio\">péritonite</span>).</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"225-17","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la sémiologie de l’ischémie intestinale aiguë et chronique : signes fonctionnels et signes physiques","contenu":"<h4 style=\"margin:4px 0 6px;font-size:14px;\">Ischémie intestinale chronique</h4>\n      <p><span class=\"kw-def\">Terrain</span> : patient âgé (vers <span class=\"kw-chiffre\">60 ans</span>), à terrain cardiovasculaire, avec une <strong>prédominance féminine (<span class=\"kw-chiffre\">70 %</span>)</strong>. La sémiologie repose sur une <span class=\"kw-def\">triade clinique</span> :</p>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Angor mésentérique</span></strong> — signe le plus précoce et le plus constant : <span class=\"kw-clinique\">crampe post-prandiale</span> survenant <span class=\"kw-chiffre\">15-30 min</span> après l'ingestion, de siège péri-ombilical ou épigastrique, d'intensité proportionnelle au volume et à la composition du repas, s'atténuant lentement en <span class=\"kw-chiffre\">1-2 h</span>.</li>\n        <li><strong>Éviction et fractionnement alimentaire</strong> — par crainte des douleurs, pouvant conduire à une dénutrition sévère.</li>\n        <li><strong><span class=\"kw-clinique\">Amaigrissement</span></strong> — souvent important, conséquence de la dénutrition.</li>\n      </ul>\n      <p>Signes physiques : <span class=\"kw-clinique\">souffle abdominal</span> souvent présent, autres localisations athéromateuses.</p>\n      <div class=\"callout callout-warn\">\n        <strong>Syndrome de <span class=\"kw-alerte\">menace</span> mésentérique.</strong> Haut risque d'<span class=\"kw-clinique\">évolution</span> vers l'ischémie intestinale aiguë — à évoquer si la douleur devient <span class=\"kw-alerte\">permanente</span> ou <span class=\"kw-alerte\">nocturne et insomniante</span>.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Ischémie intestinale aiguë</h4>\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-def\">Stade</span></th><th>Sémiologie</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Stade</span> initial</strong></td><td><span class=\"kw-clinique\">Douleur abdominale</span> = 1ᵉʳ symptôme, le plus constant : début brutal, intensité <span class=\"kw-alerte\">croissante et très intense, sans répit</span>, sans position <span class=\"kw-ttt\">antalgique</span>. <strong>Dissociation entre l'intensité de la douleur et la pauvreté de l'examen abdominal.</strong> Diarrhées fréquentes. Signes négatifs : pas de <span class=\"kw-clinique\">fièvre</span>, abdomen non distendu, pas de signes péritonéaux.</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Stade</span> tardif</strong></td><td>Tableau d'<span class=\"kw-etio\">infarctus intestinal</span> : occlusion (météorisme, <span class=\"kw-clinique\">vomissements</span> fécaloïdes, abolition des bruits hydro-aériques), puis <span class=\"kw-alerte\">signes péritonéaux</span> (défense, contracture). Signes généraux : <span class=\"kw-alerte\">fièvre</span>, <span class=\"kw-alerte\">état de choc</span> progressif, <span class=\"kw-alerte\">défaillance</span> multiviscérale ; hématochézie.</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Biologie</strong> — <span class=\"kw-bio\">hyperleucocytose</span>, <span class=\"kw-bio\">acidose métabolique</span>, élévation des <span class=\"kw-bio\">lactates</span> et des <span class=\"kw-bio\">LDH</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 269 — <span class=\"kw-clinique\">Douleur abdominale</span> aiguë · 357 — Péritonite aiguë · 355 — Hémorragie digestive</em></p>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p><strong>Ischémie aiguë de membre <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> absolue</span></strong></p><p><span class=\"kw-def\">diagnostic clinique</span> — aucun examen ne doit retarder la <span class=\"kw-ttt\">revascularisation</span></p><ul><li>Chronologie de souffrance : nerfs <span class=\"kw-chiffre\">&lt; 2h</span> · muscles <span class=\"kw-chiffre\">6-8h</span> (<span class=\"kw-alerte\">rhabdomyolyse</span>) · <span class=\"kw-clinique\">nécrose</span> cutanée <span class=\"kw-chiffre\">24h</span></li><li><span class=\"kw-ttt\">Héparine non fractionnée</span> dès le diagnostic + <span class=\"kw-ttt\">antalgiques de niveau 3</span></li><li><span class=\"kw-ttt\">Revascularisation</span> dans les <span class=\"kw-chiffre\">&lt; 6h</span></li></ul><p><strong>AAA rompu <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> extrême</span></strong></p><p>centre de <span class=\"kw-ttt\">chirurgie vasculaire</span> en <span class=\"kw-alerte\">urgence</span> ; <span class=\"kw-ttt\">bloc d'emblée</span> si patient instable (aucune <span class=\"kw-imagerie\">imagerie</span> ne doit retarder)</p><ul><li><span class=\"kw-def\">Mortalité</span> globale <span class=\"kw-alerte\">&gt; 80 %</span></li><li><span class=\"kw-clinique\">Douleur abdominale ou lombaire</span> + <span class=\"kw-alerte\">choc hémorragique</span></li></ul><p><strong>Ischémie intestinale aiguë <span class=\"q\">— <span class=\"kw-clinique\">infarctus</span> mésentérique</span></strong></p><p><span class=\"kw-imagerie\">angio-TDM</span> en <span class=\"kw-alerte\">urgence</span> + <span class=\"kw-ttt\">revascularisation</span> (endovasculaire ou <span class=\"kw-ttt\">pontage</span>)</p><ul><li>Lésions <span class=\"kw-alerte\">irréversibles dès</span> <span class=\"kw-chiffre\">4h</span> (<span class=\"kw-clinique\">nécrose</span> transpariétale)</li><li><span class=\"kw-clinique\">Douleur abdominale</span> brutale, intense, sans répit, contrastant avec la pauvreté de l'examen</li></ul>","hospit":"<p><strong><span class=\"kw-alerte\">Urgence</span> chirurgicale :</strong> <span class=\"kw-alerte\">ischémie aiguë de membre</span>, <span class=\"kw-alerte\">AAA rompu ou douloureux</span> → centre de <span class=\"kw-ttt\">chirurgie vasculaire</span>, <span class=\"kw-ttt\">artériographie au bloc opératoire</span>.<br><strong>Ambulatoire :</strong> <span class=\"kw-def\">AOMI</span> avec <span class=\"kw-clinique\">claudication</span> → <span class=\"kw-ttt\">réadaptation à la marche supervisée</span> en centre.<br><strong>Programmé :</strong> <span class=\"kw-ttt\">revascularisation</span> d'<span class=\"kw-def\">AOMI</span> ou cure d'<span class=\"kw-def\">AAA</span> (seuil <span class=\"kw-chiffre\">50-55 mm</span>) selon le <span class=\"kw-def\">terrain</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Paralysie</span> = <span class=\"kw-alerte\">ischémie aiguë</span> <span class=\"kw-def\">complète</span> : impossibilité de <span class=\"kw-clinique\">mobiliser les orteils</span> / de <span class=\"kw-clinique\">relever le pied</span></li><li><span class=\"kw-alerte\">Anesthésie cutanée</span> + <span class=\"kw-clinique\">douleur à la palpation des masses musculaires</span> (ischémie musculaire)</li><li><span class=\"kw-alerte\">Ischémie dépassée</span> : <span class=\"kw-clinique\">rigidité musculaire</span>, <span class=\"kw-clinique\">marbrures</span>, <span class=\"kw-clinique\">phlyctènes</span> → amputation d'emblée</li><li><span class=\"kw-alerte\">Occlusion de la bifurcation aortique</span> : ischémie bilatérale + <span class=\"kw-alerte\">collapsus cardiovasculaire</span></li><li>Ischémie permanente d'<span class=\"kw-def\">AOMI</span> : <span class=\"kw-clinique\">douleur de repos</span> <span class=\"kw-chiffre\">&gt; 15 jours</span>, pression de cheville <span class=\"kw-alerte\">&lt; 50 mmHg</span> / orteil <span class=\"kw-alerte\">&lt; 30 mmHg</span> (risque d'amputation)</li><li><span class=\"kw-alerte\">AAA</span> : <span class=\"kw-clinique\">masse abdominale battante</span> douloureuse + <span class=\"kw-alerte\">choc hémorragique</span> (<span class=\"kw-alerte\">rupture</span>)</li><li>Ischémie intestinale : <span class=\"kw-alerte\">syndrome de menace mésentérique</span> (douleur permanente ou nocturne insomniante), puis <span class=\"kw-alerte\">signes péritonéaux</span> + <span class=\"kw-alerte\">état de choc</span></li></ul>","principes":"<p>Double cible : un traitement à <strong>visée générale</strong> (<span class=\"kw-def\">pronostic</span> cardiovasculaire et vital) et un traitement à <strong>visée locale</strong> (symptômes et pronostic du membre).</p><p><strong>AOMI <span class=\"q\">— maladie systémique</span></strong></p><p><span class=\"kw-ttt\">β-bloquants</span> avec <span class=\"kw-ci\">prudence si ischémie critique non revascularisable</span></p><ul><li>Mesures générales : <span class=\"kw-ttt\">arrêt du tabac</span>, <span class=\"kw-ttt\">marche supervisée</span> <span class=\"kw-chiffre\">30-45 min, ≥ 3×/semaine</span></li><li>BASIC <span class=\"kw-etio\">médicamenteux</span> : <span class=\"kw-ttt\">antiplaquettaire</span> + <span class=\"kw-ttt\">statine</span> (<span class=\"kw-bio\">LDL &lt; 0,55 g/L</span>) + <span class=\"kw-ttt\">IEC</span> (même sans <span class=\"kw-def\">HTA</span>)</li><li><span class=\"kw-ttt\">Revascularisation</span> si ischémie permanente ou <span class=\"kw-clinique\">claudication</span> invalidante (<span class=\"kw-chiffre\">&lt; 100 m</span>) après TT médical <span class=\"kw-chiffre\">&gt; 3-6 mois</span></li></ul><p><strong>Ischémie aiguë de membre</strong></p><p><span class=\"kw-ci\">thrombolyse in situ contre-indiquée si ischémie sensitivo-motrice</span></p><ul><li><span class=\"kw-ttt\">Héparine non fractionnée</span> (<span class=\"kw-bio\">TCA 2-3</span>) + <span class=\"kw-ttt\">antalgie</span> dès le diagnostic</li><li><span class=\"kw-ttt\">Revascularisation</span> <span class=\"kw-chiffre\">&lt; 6h</span> : <span class=\"kw-ttt\">embolectomie par sonde de Fogarty</span> (embolie) ou <span class=\"kw-ttt\">endartériectomie / pontage</span> (thrombose)</li><li><span class=\"kw-ttt\">Aponévrotomie</span> si <span class=\"kw-alerte\">syndrome des loges</span> ; <span class=\"kw-ttt\">amputation</span> si ischémie dépassée</li></ul><p><strong>AAA</strong></p><p>seul le <span class=\"kw-chiffre\">diamètre maximal</span> compte (la longueur et le <span class=\"kw-etio\">thrombus</span> ne modifient pas la décision)</p><ul><li><span class=\"kw-alerte\">Aucun médicament</span> ne limite la croissance ni ne prévient la <span class=\"kw-alerte\">rupture</span></li><li><span class=\"kw-etio\">FRCV</span> communs : <span class=\"kw-ttt\">arrêt du tabac</span>, <span class=\"kw-ttt\">statine</span>, <span class=\"kw-ttt\">antiplaquettaire</span>, <span class=\"kw-ttt\">IEC/ARA2</span></li><li><span class=\"kw-ttt\">Chirurgie</span> (mise à plat-greffe ou <span class=\"kw-ttt\">endoprothèse EVAR</span>) si <span class=\"kw-clinique\">diamètre</span> <span class=\"kw-chiffre\">&gt; 50-55 mm</span> ou croissance <span class=\"kw-alerte\">&gt; 1 cm/an</span></li></ul><p><strong>Ischémie intestinale aiguë</strong></p><p><span class=\"kw-def\">pronostic</span> dépendant de l'étendue de la <span class=\"kw-clinique\">nécrose</span> intestinale</p><ul><li><span class=\"kw-ttt\">Revascularisation</span> endovasculaire ou par <span class=\"kw-ttt\">pontage</span> sans délai</li><li><span class=\"kw-ttt\">Laparotomie</span> + <span class=\"kw-ttt\">résection des anses nécrotiques</span> si signes généraux</li></ul>","suivi":"<p><strong>AOMI revascularisée</strong></p><ul><li><span class=\"kw-def\">Surveillance</span> clinique + <span class=\"kw-imagerie\">écho-Doppler</span> (risque de <span class=\"kw-alerte\">thrombose de stent ou de pontage</span>)</li><li><span class=\"kw-bio\">IPS &lt; 0,90</span> = marqueur de risque cardiovasculaire élevé</li></ul><p><strong>AAA</strong></p><ul><li>Non opéré : <span class=\"kw-imagerie\">échographie</span> <span class=\"kw-chiffre\">1×/an</span> si <span class=\"kw-chiffre\">&lt; 40 mm</span>, tous les <span class=\"kw-chiffre\">6 mois</span> si <span class=\"kw-chiffre\">40-49 mm</span></li><li>Post-<span class=\"kw-ttt\">chirurgie</span> conventionnelle : <span class=\"kw-imagerie\">écho-Doppler</span> annuel (<span class=\"kw-alerte\">anévrisme anastomotique</span>)</li><li>Post-EVAR : <span class=\"kw-imagerie\">écho-Doppler</span> ou <span class=\"kw-imagerie\">angio-TDM</span> au long cours (<span class=\"kw-alerte\">endofuite</span>, migration)</li><li>Découverte d'un AAA → rechercher un <span class=\"kw-clinique\">anévrisme poplité</span> (<span class=\"kw-chiffre\">30 %</span>), iliaque, aortique thoracique</li></ul><p><strong>Après <span class=\"kw-alerte\">ischémie aiguë</span> de membre</strong></p><ul><li>Surveiller le <span class=\"kw-alerte\">syndrome de revascularisation</span> : <span class=\"kw-bio\">kaliémie</span>, <span class=\"kw-bio\">CPK</span>, <span class=\"kw-bio\">créatinine</span>, diurèse (<span class=\"kw-alerte\">IRA</span>, <span class=\"kw-alerte\">CIVD</span>)</li><li>Bilan étiologique : <span class=\"kw-imagerie\">Holter</span>, <span class=\"kw-imagerie\">ETT ± ETO</span>, <span class=\"kw-imagerie\">écho-Doppler</span> artériel</li><li>Cause <span class=\"kw-etio\">embolique</span> → <span class=\"kw-ttt\">anticoagulation au long cours</span> (ex. <span class=\"kw-etio\">FA</span>) ; cause <span class=\"kw-etio\">thrombotique</span> → <span class=\"kw-ttt\">antiagrégant</span> + <span class=\"kw-etio\">FRCV</span></li></ul>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/abdominal-aortic-aneurysm","label":"Radiopaedia : Abdominal aortic aneurysm"},{"href":"https://radiopaedia.org/articles/peripheral-arterial-disease","label":"Radiopaedia : Peripheral arterial disease"},{"href":"https://www.sfcardio.fr/page/chapitre-7-item-225-arteriopathie-de-laorte-des-arteres-viscerales-et-des-membres-inferieurs","label":"SFC — Chapitre 7 item 225 arteriopathie de laorte des arteres viscerales et des membres inferieurs"},{"href":"https://www.youtube.com/watch?v=8NYq4UJO-sA","label":"YouTube — Watch"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Ischémie aiguë de membre : froid, pâle, douloureux, pouls abolis en aval — <span class=\"kw-alerte\">Urgence</span> absolue — <span class=\"kw-ttt\">héparine non fractionnée</span> + antalgie d'emblée · diagnostic clinique, ne pas retarder la <span class=\"kw-ttt\">revascularisation</span> (<span class=\"kw-chiffre\">< 6</span>h)","detail":"<h4>CAT — <span class=\"kw-alerte\">ischémie aiguë</span> de membre — Évaluer la viabilité du membre, puis orienter le mécanisme et la <span class=\"kw-ttt\">revascularisation</span></h4>","branches":[{"to":"t-depassee","label":"Ischémie dépassée : rigidité musculaire, marbrures, phlyctènes","color":"red"},{"to":"q-meca","label":"Membre viable ou menacé (pas de signe d'ischémie dépassée)","color":"amber"}]},{"id":"t-depassee","kind":"terminal","label":"Ischémie dépassée — membre non récupérable","color":"red","detail":"<h4>Reconnaître</h4><ul><li><span class=\"kw-alerte\">Rigidité musculaire</span>, <span class=\"kw-alerte\">marbrures</span>, <span class=\"kw-alerte\">phlyctènes</span> = lésions irréversibles</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Amputation d'emblée</span> (la <span class=\"kw-ttt\">revascularisation</span> ferait courir un <span class=\"kw-alerte\">risque vital</span> par <span class=\"kw-clinique\">syndrome de revascularisation</span>)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Prévention du <span class=\"kw-alerte\">syndrome de revascularisation</span> : <span class=\"kw-bio\">kaliémie</span>, <span class=\"kw-bio\">CPK</span>, <span class=\"kw-bio\">créatinine</span>, diurèse</li></ul>"},{"id":"q-meca","kind":"decision","label":"Orientation étiologique : terrain et mode de début ? — ECG systématique · écho-Doppler possible si grade I sans atteinte neurologique, sans perte de temps","branches":[{"to":"t-embolie","label":"Embolie sur artères saines : sujet jeune, cardiopathie emboligène, début très brutal","color":"red"},{"to":"t-thrombose","label":"Thrombose in situ : AOMI / FRCV, début progressif (collatéralité)","color":"amber"},{"to":"t-bifurcation","label":"Occlusion de la bifurcation aortique : ischémie bilatérale + collapsus","color":"red"}]},{"id":"t-embolie","kind":"terminal","label":"Embolie sur artères saines","color":"red","detail":"<h4><span class=\"kw-def\">Terrain</span></h4><ul><li>Sujet jeune sans ATCD vasculaire, <span class=\"kw-etio\">cardiopathie emboligène</span> (<span class=\"kw-etio\">FA</span>, valvulopathie, <span class=\"kw-etio\">IDM</span> / anévrisme du VG, myxome) ; <span class=\"kw-clinique\">douleur très brutale</span>, parfois après <span class=\"kw-clinique\">palpitations</span></li></ul><h4><span class=\"kw-ttt\">Revascularisation</span> (< 6h)</h4><ul><li><span class=\"kw-ttt\">Embolectomie par sonde de Fogarty</span> sous contrôle angiographique</li></ul><h4>Au long cours</h4><ul><li>Bilan cardiaque (<span class=\"kw-imagerie\">Holter</span>, <span class=\"kw-imagerie\">ETT ± ETO</span>) + <span class=\"kw-ttt\">anticoagulation au long cours</span> si <span class=\"kw-etio\">FA</span></li></ul><h4>Renvoi</h4><ul><li>Item 232 (<span class=\"kw-clinique\">fibrillation</span> atriale)</li></ul>"},{"id":"t-thrombose","kind":"terminal","label":"Thrombose in situ sur artère pathologique","color":"amber","detail":"<h4><span class=\"kw-def\">Terrain</span></h4><ul><li>Sujet âgé à <span class=\"kw-etio\">FRCV</span>, <span class=\"kw-etio\">AOMI</span> préexistante ; <span class=\"kw-clinique\">douleur d'installation progressive</span> (collatéralité préexistante)</li></ul><h4><span class=\"kw-ttt\">Revascularisation</span> (< 6h)</h4><ul><li>Techniques conventionnelles (<span class=\"kw-ttt\">endartériectomie</span>, <span class=\"kw-ttt\">pontage</span>) ou endovasculaires (<span class=\"kw-ttt\">recanalisation</span>, <span class=\"kw-ttt\">angioplastie</span>, <span class=\"kw-ttt\">thrombo-aspiration</span>)</li></ul><h4><span class=\"kw-ci\">Contre-indication</span></h4><ul><li><span class=\"kw-ci\">Thrombolyse in situ contre-indiquée si ischémie sensitivo-motrice</span> (délai d'action trop long, caillot volumineux)</li></ul><h4>Au long cours</h4><ul><li><span class=\"kw-ttt\">Antiagrégant plaquettaire</span> + contrôle des <span class=\"kw-etio\">FRCV</span></li></ul>"},{"id":"t-bifurcation","kind":"terminal","label":"Occlusion de la bifurcation aortique","color":"red","detail":"<h4>Tableau</h4><ul><li><span class=\"kw-alerte\">Ischémie bilatérale sévère</span> + <span class=\"kw-alerte\">paralysie sensitivomotrice</span> ; signes généraux au premier plan jusqu'au <span class=\"kw-alerte\">collapsus cardiovasculaire</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Urgence</span> vitale : <span class=\"kw-ttt\">réanimation hémodynamique</span> + <span class=\"kw-ttt\">revascularisation chirurgicale immédiate</span></li></ul><h4>Renvoi</h4><ul><li>Item 332 (<span class=\"kw-alerte\">état de choc</span>)</li></ul>"}]},"cards":[{"i":"34afcaf7e887","n":225,"o":"225-10","u":"Définition","t":"Connaître la définition et l’histoire naturelle d’un anévrisme de l’aorte abdominale et savoir rechercher d’autres localisations anévrismales","q":"Comment définit-on un anévrisme artériel ?","a":"<p>Un anévrisme artériel est une <strong>dilatation focale et permanente</strong> d'une artère, avec perte du parallélisme de ses parois, dont le diamètre est <strong>&gt; 1,5 fois le diamètre d'amont</strong>. La dilatation peut être fusiforme ou sacciforme.</p>"},{"i":"3b91b8bde8f2","n":225,"o":"225-10","u":"Définition","t":"Connaître la définition et l’histoire naturelle d’un anévrisme de l’aorte abdominale et savoir rechercher d’autres localisations anévrismales","q":"Lors de la découverte d'un anévrisme de l'aorte abdominale (AAA), quelles autres localisations anévrismales doit-on rechercher systématiquement et avec quelles modalités d'imagerie ?","a":"<ul><li><strong>Anévrisme poplité</strong> : Associé dans 30% des cas, à rechercher par <strong>échographie-Doppler des artères des membres inférieurs</strong>.</li><li><strong>Anévrisme des artères iliaques</strong> : À rechercher par <strong>échographie-Doppler ou angio-TDM</strong>.</li><li><strong>Anévrisme de l'aorte thoracique</strong> : À rechercher par <strong>angio-TDM thoraco-abdomino-pelvienne</strong>.</li><li>Il convient également de dépister l'<strong>athérosclérose</strong>, notamment coronarienne et des troncs supra-aortiques.</li></ul>"},{"i":"47b517bb1431","n":225,"o":"225-10","u":"Définition","t":"Connaître la définition et l’histoire naturelle d’un anévrisme de l’aorte abdominale et savoir rechercher d’autres localisations anévrismales","q":"Quelle est la définition, selon la HAS, d'un anévrisme de l'aorte abdominale (AAA) ?","a":"<p>Un anévrisme de l'aorte abdominale est défini par un <strong>diamètre antéro-postérieur &gt; 30 mm</strong>, ou une dilatation <strong>&ge; +50%</strong> par rapport au diamètre de l'aorte abdominale sus-jacente normale.</p>"},{"i":"d126560e2641","n":225,"o":"225-10","u":"Définition","t":"Connaître la définition et l’histoire naturelle d’un anévrisme de l’aorte abdominale et savoir rechercher d’autres localisations anévrismales","q":"Quelle est l'histoire naturelle de la croissance d'un anévrisme de l'aorte abdominale (AAA) et quels sont les facteurs influençant son risque de rupture ?","a":"<ul><li><strong>Croissance</strong> : En moyenne de <strong>2 à 4 mm/an</strong>. Elle est d'autant plus rapide que le diamètre est grand. Un AAA est dit à « croissance rapide » si sa croissance est &gt; 1 cm/an.</li><li><strong>Risque de rupture</strong> : Il augmente avec le diamètre (< 0,5% par an si diamètre &lt; 40 mm, puis croissant). Ce risque est <strong>majoré chez la femme</strong> à diamètre égal (multiplié par 4).</li></ul>"},{"i":"3ad50bace82d","n":225,"o":"225-12","u":"Diagnostic positif","t":"Connaître les signes cliniques des anévrismes de l’aorte","q":"Quels sont les signes cliniques les plus fréquents d'un anévrisme de l'aorte abdominale non compliqué, et comment est-il généralement découvert ?","a":"<p>L'anévrisme de l'aorte abdominale est le plus souvent <strong>asymptomatique</strong> et découvert de façon fortuite. Cliniquement, il peut se présenter comme une <strong>masse abdominale battante et expansive</strong> de la région para-ombilicale, avec ou sans souffle. Elle est palpable surtout chez les sujets maigres ou si l'anévrisme est volumineux. La découverte se fait également par imagerie (échographie, TDM, IRM).</p>"},{"i":"3b77051bba8d","n":225,"o":"225-12","u":"Diagnostic positif","t":"Connaître les signes cliniques des anévrismes de l’aorte","q":"Quels sont les signes cliniques et biologiques d'un anévrisme de l'aorte inflammatoire ?","a":"<p>Un anévrisme de l'aorte inflammatoire, dû à une gangue inflammatoire péri-anévrismale, se manifeste par une <strong>fièvre</strong>, une <strong>altération de l'état général (AEG)</strong> et un <strong>syndrome inflammatoire biologique</strong> (augmentation de la vitesse de sédimentation (VS) et de la C-réactive protéine (CRP)).</p>"},{"i":"4d5f5db3a9a2","n":225,"o":"225-12","u":"Diagnostic positif","t":"Connaître les signes cliniques des anévrismes de l’aorte","q":"Quels sont les signes cliniques d'une complication embolique à partir d'un anévrisme de l'aorte abdominale ?","a":"<p>Une complication embolique à partir du thrombus intra-anévrismal peut se manifester par une <strong>occlusion artérielle aiguë du membre inférieur</strong> ou des <strong>embolies de cristaux de cholestérol</strong> (par exemple, un orteil bleu).</p>"},{"i":"4f74b63beaa1","n":225,"o":"225-12","u":"Diagnostic positif","t":"Connaître les signes cliniques des anévrismes de l’aorte","q":"Quels sont les syndromes cliniques liés à la compression des organes adjacents par un anévrisme de l'aorte abdominale ?","a":"<ul><li>Compression du <strong>duodénum</strong> : vomissements post-prandiaux.</li><li>Compression des <strong>nerfs</strong> : radiculalgies.</li><li>Compression de la <strong>veine cave inférieure (VCI)</strong> : œdèmes des membres inférieurs.</li><li>Compression des <strong>os</strong> : érosions vertébrales.</li><li>Compression des <strong>voies urinaires</strong> : coliques néphrétiques.</li></ul>"},{"i":"972ae32c0cce","n":225,"o":"225-12","u":"Diagnostic positif","t":"Connaître les signes cliniques des anévrismes de l’aorte","q":"Quels sont les signes cliniques évocateurs d'une fissuration ou d'une rupture d'anévrisme de l'aorte abdominale ?","a":"<p>Une fissuration ou une rupture d'anévrisme de l'aorte abdominale se traduit cliniquement par une <strong>douleur abdominale ou lombaire</strong>, pouvant être associée à un <strong>tableau de choc hémorragique</strong>. On distingue la rupture rétropéritonéale (syndrome fissuraire) et la rupture intrapéritonéale (souvent foudroyante).</p>"},{"i":"9a64b9d4aebd","n":225,"o":"225-12","u":"Diagnostic positif","t":"Connaître les signes cliniques des anévrismes de l’aorte","q":"Quelles sont les manifestations cliniques des fistules aortiques ?","a":"<ul><li>Une <strong>fistule aorto-cave</strong> provoque une <strong>insuffisance cardiaque à débit élevé</strong>.</li><li>Une <strong>fistule aorto-digestive</strong> entraîne une <strong>hémorragie digestive</strong> (hématémèse, rectorragie).</li></ul>"},{"i":"ed3d9ae54033","n":225,"o":"225-12","u":"Diagnostic positif","t":"Connaître les signes cliniques des anévrismes de l’aorte","q":"Comment le signe de Bakey peut-il orienter sur la localisation d'un anévrisme de l'aorte abdominale ?","a":"<p>Le <strong>signe de Bakey</strong> correspond à la possibilité de glisser la main entre le pôle supérieur de l'anévrisme et les côtes du patient. Sa présence est en faveur d'un <strong>anévrisme sous-rénal</strong>.</p>"},{"i":"1a0d07511a89","n":225,"o":"225-13","u":"Examens complémentaires","t":"Savoir comment faire le diagnostic des anévrysmes de l’aorte abdominale","q":"Quelle est la place de l'artériographie dans le diagnostic des anévrismes de l'aorte abdominale (AAA) ?","a":"<p>L'artériographie n'a <strong>plus d'indication diagnostique</strong> pour les anévrismes de l'aorte abdominale (AAA) car elle ne révèle que la lumière artérielle et ne permet pas une mesure fiable du diamètre en raison du thrombus mural fréquent.</p>"},{"i":"3d7951002dcf","n":225,"o":"225-13","u":"Examens complémentaires","t":"Savoir comment faire le diagnostic des anévrysmes de l’aorte abdominale","q":"Quel est l'examen de référence pour l'évaluation pré-thérapeutique d'un anévrisme de l'aorte abdominale (AAA) ?","a":"<p>L'examen de référence pour l'évaluation pré-thérapeutique d'un anévrisme de l'aorte abdominale (AAA) est la <strong>TDM thoraco-abdomino-pelvienne injectée</strong>. Elle précise les diamètres et l'extension par rapport aux artères rénales et iliaques.</p>"},{"i":"4afd80fbbc8b","n":225,"o":"225-13","u":"Examens complémentaires","t":"Savoir comment faire le diagnostic des anévrysmes de l’aorte abdominale","q":"Quels éléments ne modifient pas la prise en charge d'un anévrisme de l'aorte abdominale (AAA), le diamètre étant le critère principal ?","a":"<p>La <strong>longueur de l'AAA</strong> et la <strong>présence d'un thrombus endoluminal</strong> ne modifient pas la prise en charge. Seul le <strong>diamètre maximal</strong> compte pour la décision thérapeutique.</p>"},{"i":"cac2503e4be6","n":225,"o":"225-13","u":"Examens complémentaires","t":"Savoir comment faire le diagnostic des anévrysmes de l’aorte abdominale","q":"Quelle recherche systématique doit être menée lors de la découverte d'un anévrisme de l'aorte abdominale (AAA) ?","a":"<p>La découverte d'un AAA justifie la recherche systématique d'un anévrisme <strong>poplité</strong> (associé dans <strong>30 %</strong> des cas), des artères iliaques, de l'aorte thoracique, et le dépistage des affections des coronaires et des troncs supra-aortiques.</p>"},{"i":"e4ce99563360","n":225,"o":"225-13","u":"Examens complémentaires","t":"Savoir comment faire le diagnostic des anévrysmes de l’aorte abdominale","q":"Dans quel cas une TDM thoraco-abdomino-pelvienne injectée est-elle indiquée en urgence pour un anévrisme de l'aorte abdominale (AAA) ?","a":"<p>Une TDM thoraco-abdomino-pelvienne injectée est indiquée en urgence en cas d'<strong>AAA douloureux</strong> ou de <strong>suspicion de rupture</strong>.</p>"},{"i":"f3cbf68f204c","n":225,"o":"225-13","u":"Examens complémentaires","t":"Savoir comment faire le diagnostic des anévrysmes de l’aorte abdominale","q":"Quel est l'examen de dépistage et de suivi de première intention pour un anévrisme de l'aorte abdominale (AAA) asymptomatique ?","a":"<p>L'examen de dépistage et de suivi de première intention pour un anévrisme de l'aorte abdominale (AAA) asymptomatique est l'<strong>échographie abdominale</strong>. Elle permet d'obtenir le diamètre maximal et de surveiller la croissance de l'anévrisme.</p>"},{"i":"1518d7b4458a","n":225,"o":"225-15","u":"Identifier une urgence","t":"Savoir reconnaître et prendre en charge une situation d’urgence chez les patient porteur d’un anévrisme de l’aorte abdominale","q":"Quelle est la prise en charge d'une ischémie aiguë du membre inférieur compliquant un AAA ?","a":"<p>L'ischémie aiguë du membre inférieur, souvent due à une embolie à partir du thrombus de l'AAA, nécessite une <strong>prise en charge spécifique immédiate par embolectomie</strong>. L'AAA sera traité secondairement.</p>"},{"i":"54b37c208b63","n":225,"o":"225-15","u":"Identifier une urgence","t":"Savoir reconnaître et prendre en charge une situation d’urgence chez les patient porteur d’un anévrisme de l’aorte abdominale","q":"Comment identifier et prendre en charge d'une fistule aorto-digestive liée à un AAA ?","a":"<p>Une fistule aorto-digestive se manifeste par une <strong>hémorragie digestive</strong> (<strong>hématémèse</strong> ou <strong>rectorragie</strong>) associée à une <strong>défaillance hémodynamique</strong>. C'est une urgence absolue en chirurgie vasculaire et nécessite une <strong>intervention immédiate</strong>.</p>"},{"i":"61b20f37f977","n":225,"o":"225-15","u":"Identifier une urgence","t":"Savoir reconnaître et prendre en charge une situation d’urgence chez les patient porteur d’un anévrisme de l’aorte abdominale","q":"Quand est-ce qu'une TDM peut être réalisée chez un patient suspect d'AAA rompu ?","a":"<p>Une TDM peut être réalisée uniquement si l'<strong>état hémodynamique le permet</strong>. Elle ne doit en aucun cas retarder une intervention chirurgicale chez un patient en choc hémorragique.</p>"},{"i":"81295e1007bf","n":225,"o":"225-15","u":"Identifier une urgence","t":"Savoir reconnaître et prendre en charge une situation d’urgence chez les patient porteur d’un anévrisme de l’aorte abdominale","q":"Comment doit être pris en charge un patient présentant un AAA douloureux (non rompu) en urgence ?","a":"<p>Un AAA douloureux nécessite une <strong>TDM en urgence</strong>, une prise en charge de l'<strong>état général, cardiovasculaire, rénal et respiratoire</strong>, et une <strong>hospitalisation rapide pour intervention</strong>.</p>"},{"i":"cc360c871990","n":225,"o":"225-15","u":"Identifier une urgence","t":"Savoir reconnaître et prendre en charge une situation d’urgence chez les patient porteur d’un anévrisme de l’aorte abdominale","q":"Quelle est la conduite à tenir en urgence face à un patient présentant un anévrisme de l'aorte abdominale (AAA) rompu ?","a":"<p>Un AAA rompu est une <strong>urgence extrême</strong>. La conduite à tenir est une orientation immédiate vers un <strong>centre spécialisé de chirurgie vasculaire</strong>. Si le patient est en <strong>choc hémorragique</strong>, aucune imagerie ne doit retarder l'intervention. Si les mesures de réanimation ne stabilisent pas le patient, un <strong>passage direct au bloc opératoire</strong> est indiqué.</p>"},{"i":"d4d101ab20e9","n":225,"o":"225-15","u":"Identifier une urgence","t":"Savoir reconnaître et prendre en charge une situation d’urgence chez les patient porteur d’un anévrisme de l’aorte abdominale","q":"Quelle est la conduite à tenir face à une fistule aorto-cave suite à un AAA ?","a":"<p>Une fistule aorto-cave se manifeste par une <strong>insuffisance cardiaque à débit élevé</strong> (défaillance hémodynamique sans déglobulisation) et constitue une urgence absolue en chirurgie vasculaire, nécessitant une <strong>intervention immédiate</strong>.</p>"},{"i":"3e27692bd3f7","n":225,"o":"225-16","u":"Définition","t":"Connaître la définition de l’ischémie intestinale aiguë et chronique","q":"Quelle est la définition de l'ischémie intestinale aiguë (ou infarctus mésentérique) ?","a":"<p>L'ischémie intestinale aiguë est une <strong>interruption brutale de la vascularisation</strong> intestinale, causée par une <strong>occlusion artérielle</strong>. Les mécanismes d'occlusion incluent la <strong>thrombose in situ</strong>, l'<strong>embolie</strong> ou la <strong>dissection</strong>. La muqueuse est la première à souffrir, avec des lésions irréversibles (nécrose transpariétale) dès <strong>4 heures</strong>, pouvant conduire à un <strong>infarctus mésentérique</strong>, avec un risque élevé de perforation et de péritonite.</p>"},{"i":"97a5ef226388","n":225,"o":"225-16","u":"Définition","t":"Connaître la définition de l’ischémie intestinale aiguë et chronique","q":"Quelle est la définition de l'ischémie intestinale chronique ?","a":"<p>L'ischémie intestinale chronique est caractérisée par des <strong>sténoses artérielles progressives</strong> (principalement par athéromatose dans 95 % des cas) au niveau des axes mésentériques. Pour devenir symptomatique, au moins <strong>deux des trois axes artériels principaux</strong> doivent être touchés. Elle se manifeste cliniquement par une douleur post-prandiale due à l'hypoperfusion.</p>"},{"i":"c28ccbb60330","n":225,"o":"225-16","u":"Définition","t":"Connaître la définition de l’ischémie intestinale aiguë et chronique","q":"Pourquoi l'ischémie du grêle est-elle particulièrement grave ?","a":"<p>L'ischémie du grêle est particulièrement grave car la vascularisation du grêle est <strong>terminale</strong>. Cela signifie que ses suppléances anastomotiques sont peu développées, rendant le risque d'ischémie très élevé en cas d'interruption du flux sanguin.</p>"},{"i":"d5dd03197db9","n":225,"o":"225-16","u":"Définition","t":"Connaître la définition de l’ischémie intestinale aiguë et chronique","q":"Quels sont les principaux axes artériels assurant la vascularisation du tube digestif ?","a":"<p>La vascularisation artérielle du tube digestif repose sur <strong>trois axes</strong> principaux :<ul><li>Le <strong>tronc cœliaque</strong> (estomac, foie, rate)</li><li>L'<strong>artère mésentérique supérieure (AMS)</strong> (jéjunum, iléon, cæcum, côlon droit, 1/3 droit du côlon transverse)</li><li>L'<strong>artère mésentérique inférieure (AMI)</strong> (2/3 gauches du côlon transverse, côlon gauche, sigmoïde, haut rectum)</li></ul></p>"},{"i":"33e9566b2dc1","n":225,"o":"225-17","u":"Diagnostic positif","t":"Connaître la sémiologie de l’ischémie intestinale aiguë et chronique : signes fonctionnels et signes physiques","q":"Quels signes physiques peuvent être retrouvés à l'examen clinique chez un patient présentant une ischémie intestinale chronique ?","a":"<p>À l'examen clinique d'une ischémie intestinale chronique, on peut retrouver :</p><ul><li>Un <strong>souffle abdominal</strong>, souvent présent.</li><li>D'<strong>autres localisations athéromateuses</strong>.</li></ul>"},{"i":"3f795c950a2d","n":225,"o":"225-17","u":"Diagnostic positif","t":"Connaître la sémiologie de l’ischémie intestinale aiguë et chronique : signes fonctionnels et signes physiques","q":"Quels sont les signes cliniques du stade initial de l'ischémie intestinale aiguë ?","a":"<p>Au stade initial de l'ischémie intestinale aiguë, les signes cliniques sont :</p><ul><li>Une <strong>douleur abdominale</strong> de début <strong>brutal</strong>, d'intensité <strong>croissante et très intense</strong>, sans répit et sans position antalgique.</li><li>Une <strong>discordance</strong> entre l'intensité de la douleur et la pauvreté de l'examen abdominal.</li><li>Des <strong>diarrhées fréquentes</strong>.</li><li>L'absence de fièvre, d'abdomen distendu et de signes péritonéaux (<strong>signes négatifs</strong>).</li></ul>"},{"i":"8340f6b13ce0","n":225,"o":"225-17","u":"Diagnostic positif","t":"Connaître la sémiologie de l’ischémie intestinale aiguë et chronique : signes fonctionnels et signes physiques","q":"Quelle est la triade clinique caractéristique de l'ischémie intestinale chronique ?","a":"<p>La triade clinique de l'ischémie intestinale chronique est :</p><ul><li>L'<strong>angor mésentérique</strong> : crampe post-prandiale survenant <strong>15-30 min après l'ingestion</strong>, péri-ombilicale ou épigastrique, proportionnelle au repas et s'atténuant en 1-2 h.</li><li>L'<strong>éviction et le fractionnement alimentaire</strong> par crainte des douleurs.</li><li>L'<strong>amaigrissement</strong>, souvent important et lié à la dénutrition.</li></ul>"},{"i":"dbe550ca8e2a","n":225,"o":"225-17","u":"Diagnostic positif","t":"Connaître la sémiologie de l’ischémie intestinale aiguë et chronique : signes fonctionnels et signes physiques","q":"Quels sont les signes cliniques et biologiques du stade tardif de l'ischémie intestinale aiguë ?","a":"<p>Au stade tardif de l'ischémie intestinale aiguë, traduisant un infarctus intestinal, on observe :</p><ul><li>Des signes d'<strong>occlusion</strong> (météorisme, vomissements fécaloïdes, abolition des bruits hydro-aériques).</li><li>Des <strong>signes péritonéaux</strong> (défense, contracture).</li><li>Des signes généraux : <strong>fièvre</strong>, état de choc progressif, défaillance multiviscérale.</li><li>Une <strong>hématochézie</strong>.</li><li>Biologiquement : <strong>hyperleucocytose</strong>, <strong>acidose métabolique</strong>, élévation des <strong>lactates</strong> et des <strong>LDH</strong>.</li></ul>"},{"i":"028929c99490","n":225,"o":"225-3","u":"Diagnostic positif","t":"Connaître les manifestations cliniques et la classification de l’AOMI et savoir évoquer les diagnostics différentiels","q":"Quels sont les signes cliniques caractéristiques de l'ischémie d'effort (claudication intermittente) dans l'AOMI ?","a":"<p>Les signes cliniques de l'ischémie d'effort sont :</p><ul><li><strong>Type</strong> : crampe musculaire.</li><li><strong>Topographie</strong> : typiquement au mollet, mais peut être au pied, à la cuisse ou fessière (par atteinte aorto-iliaque).</li><li><strong>Distance de gêne</strong> : distance à laquelle la douleur apparaît.</li><li><strong>Distance de marche</strong> : distance parcourue avant que la douleur n'oblige à l'arrêt (sévère si < <strong>100 m</strong> sur terrain plat).</li><li><strong>Disparition</strong> : habituellement en < <strong>5 minutes</strong> à l'arrêt.</li><li><strong>Formes atypiques</strong> : distances variables, paresthésie d'effort, ralentissement du pas sans arrêt obligé.</li></ul>"},{"i":"0a50ea375430","n":225,"o":"225-3","u":"Diagnostic positif","t":"Connaître les manifestations cliniques et la classification de l’AOMI et savoir évoquer les diagnostics différentiels","q":"Quelles sont les manifestations cliniques des stades 3 et 4 de l'AOMI (ischémie permanente ou critique) ?","a":"<p>Les manifestations cliniques de l'ischémie permanente/critique (stade 3 et 4) sont :</p><ul><li><strong>Douleur de repos (stade 3)</strong> : à type de <strong>brûlure</strong>, localisée aux orteils ou à l'avant-pied, survenant après quelques minutes/heures de décubitus, et calmée par la position <strong>déclive</strong> (jambes pendantes). Elle dure > <strong>15 jours</strong> et résiste aux antalgiques usuels.</li><li><strong>Troubles trophiques (stade 4)</strong> : peau mince et fragile, dépilation, <strong>ulcère artériel</strong>, <strong>gangrène</strong> (orteils, talon), et portes d'entrée infectieuses.</li></ul><p>L'IPS est &le; 0,9, et la pression à la cheville &le; 50 mmHg.</p>"},{"i":"63be3e4554d4","n":225,"o":"225-3","u":"Diagnostic positif","t":"Connaître les manifestations cliniques et la classification de l’AOMI et savoir évoquer les diagnostics différentiels","q":"Quelles sont les caractéristiques du Syndrome de Leriche ?","a":"<p>Le Syndrome de Leriche est une atteinte <strong>aorto-iliaque</strong> (aorte sous-rénale + artères iliaques primitives) qui associe :</p><ul><li><strong>claudication fessière bilatérale</strong> et/ou fatigabilité à la marche.</li><li><strong>dysfonction érectile</strong> chez l'homme.</li><li><strong>abolition des deux pouls fémoraux</strong>.</li><li><strong>atrophie musculaire</strong> des membres inférieurs.</li></ul>"},{"i":"673fef091762","n":225,"o":"225-3","u":"Diagnostic positif","t":"Connaître les manifestations cliniques et la classification de l’AOMI et savoir évoquer les diagnostics différentiels","q":"Comment l'abolition des pouls périphériques ou un souffle vasculaire peuvent-ils orienter vers un diagnostic d'AOMI ?","a":"<ul><li>Une sténose artérielle peut être suspectée devant un <strong>souffle vasculaire</strong>.</li><li>Une obstruction artérielle se manifeste par une <strong>abolition de pouls</strong> en aval sans souffle.</li><li>L'AOMI asymptomatique (stade 1) peut être évoquée devant un souffle vasculaire ou une abolition de pouls périphériques chez un patient à <strong>facteurs de risque cardiovasculaire (FRCV)</strong>, ou une dysfonction érectile chez un patient à FRCV. La confirmation se fait par un IPS &le; <strong>0,90</strong>.</li></ul>"},{"i":"eb28b18cd8ab","n":225,"o":"225-3","u":"Diagnostic positif","t":"Connaître les manifestations cliniques et la classification de l’AOMI et savoir évoquer les diagnostics différentiels","q":"Comment est classifiée cliniquement l'artériopathie oblitérante des membres inférieurs (AOMI) selon les stades clinico-hémodynamiques ?","a":"<p>L'AOMI est classifiée en 3 stades clinico-hémodynamiques :</p><ul><li><strong>Asymptomatique</strong> : Aucun symptôme, IPS &le; 0,9, PA cheville > 50 mmHg.</li><li><strong>Ischémie d'effort (claudication intermittente)</strong> : Douleur type crampe à l'effort, IPS &le; 0,9, PA cheville > 50 mmHg.</li><li><strong>Ischémie permanente (critique)</strong> : Douleurs de décubitus au repos &plusmn; troubles trophiques, IPS &le; 0,9, PA cheville &le; 50 mmHg.</li></ul>"},{"i":"ef4aa8b1618e","n":225,"o":"225-3","u":"Diagnostic positif","t":"Connaître les manifestations cliniques et la classification de l’AOMI et savoir évoquer les diagnostics différentiels","q":"Quels sont les diagnostics différentiels de la claudication intermittente et comment les distinguer ?","a":"<ul><li><strong>Claudication artérielle</strong> : Distance d'apparition toujours la même, douleur de type <strong>crampe musculaire</strong> obligeant à l'arrêt, récupération rapide. Contexte athéromateux.</li><li><strong>Claudication veineuse</strong> : Distance d'apparition variable, gonflement douloureux progressif n'obligeant pas à l'arrêt, récupération lente. Contexte de troubles veineux (ex: syndrome post-thrombotique).</li><li><strong>Claudication articulaire</strong> : Douleur dès les premiers pas, topographie articulaire, d'emblée maximale, récupération lente. Contexte d'arthrose ou rhumatisme inflammatoire.</li><li><strong>Claudication neurologique</strong> : Distance d'apparition variable, douleur soulagée par l'antéflexion, topographie radiculaire. Contexte de canal lombaire étroit ou arthrose lombaire.</li></ul>"},{"i":"6a993ee50230","n":225,"o":"225-4","u":"Examens complémentaires","t":"Savoir prescrire les examens complémentaires de première intention","q":"Quels sont les autres examens de première intention pertinents dans le bilan de l'AOMI, en dehors de l'IPS ?","a":"<ul><li>Le <strong>test de marche</strong> pour sensibiliser le diagnostic et confirmer l'origine artérielle de la claudication.</li><li>L'<strong>Écho-Doppler artériel</strong> pour localiser les lésions artérielles et leur retentissement hémodynamique.</li><li>La mesure de la <strong>TcPO2</strong> (Oxygène transcutané) pour évaluer l'ischémie critique.</li><li>Le <strong>bilan biologique des facteurs de risque cardiovasculaire (FRCV)</strong> (recherche de dyslipidémie, diabète, insuffisance rénale chronique).</li></ul>"},{"i":"9b3c511651e3","n":225,"o":"225-4","u":"Examens complémentaires","t":"Savoir prescrire les examens complémentaires de première intention","q":"Quel est l'examen clé de première intention pour confirmer le diagnostic de l'artériopathie oblitérante des membres inférieurs (AOMI) ?","a":"<p>L'examen clé de première intention pour confirmer le diagnostic de l'AOMI est la mesure de l'<strong>Index de Pression Systolique (IPS)</strong>.</p>"},{"i":"d9bf5f4a3cec","n":225,"o":"225-4","u":"Examens complémentaires","t":"Savoir prescrire les examens complémentaires de première intention","q":"Quand les examens de deuxième intention sont-ils envisagés dans le bilan de l'AOMI et quels sont-ils ?","a":"<p>Les examens de deuxième intention sont envisagés <strong>uniquement si une revascularisation est envisagée</strong>. Ils comprennent :</p><ul><li>L'<strong>Angio-TDM</strong>.</li><li>L'<strong>Angio-IRM</strong>.</li><li>L'<strong>Artériographie</strong>.</li></ul>"},{"i":"f547dad32720","n":225,"o":"225-4","u":"Examens complémentaires","t":"Savoir prescrire les examens complémentaires de première intention","q":"Comment interprète-t-on les valeurs de l'Index de Pression Systolique (IPS) dans le diagnostic de l'AOMI ?","a":"<ul><li>Une valeur d'IPS entre <strong>1 et 1,40</strong> est normale.</li><li>Un IPS <strong>&lt; 0,90</strong> est évocateur d'AOMI et constitue un marqueur de risque cardiovasculaire élevé.</li><li>Un IPS <strong>&lt; 0,70</strong> indique une AOMI sévère.</li><li>Un IPS <strong>&gt; 1,40</strong> suggère une <strong>médiacalcose</strong> (rigidité artérielle) rendant la pression de cheville ininterprétable.</li></ul>"},{"i":"14f6b02cf2a1","n":225,"o":"225-5","u":"Prise en charge","t":"Connaître le traitement médical : traitement médicamenteux et principes du traitement chirurgical","q":"Quelles sont les indications de la revascularisation dans l'artériopathie oblitérante des membres inférieurs (AOMI) ?","a":"<p>Les indications de la revascularisation sont :</p><ul><li>Une <strong>ischémie permanente</strong>.</li><li>Une <strong>claudication intermittente sévère</strong> après traitement médical bien mené de <strong>plus de 3-6 mois</strong>.</li><li>Un <strong>périmètre de marche très faible (< 100 m)</strong> avec un handicap important.</li><li>Des <strong>atteintes aorto-iliaques sévères et extensives</strong>.</li></ul>"},{"i":"44448f17710a","n":225,"o":"225-5","u":"Prise en charge","t":"Connaître le traitement médical : traitement médicamenteux et principes du traitement chirurgical","q":"Quelles sont les principales techniques de revascularisation dans l'artériopathie oblitérante des membres inférieurs (AOMI) et leurs principes ?","a":"<p>Les principales techniques sont :</p><ul><li>La technique <strong>endovasculaire</strong> : angioplastie intraluminale par ballonnet ± pose de stent, avec de meilleurs résultats sur les <strong>lésions courtes et proximales</strong>. Nécessite une <strong>bithérapie antiplaquettaire de 1 à 6 mois</strong>.</li><li>La <strong>chirurgie</strong> : principalement le <strong>pontage</strong> (aorto-bifémoral, fémoro-poplité, fémoro-jambier) ; une <strong>endartériectomie</strong> peut y être associée.</li></ul>"},{"i":"c0f71b79e263","n":225,"o":"225-5","u":"Prise en charge","t":"Connaître le traitement médical : traitement médicamenteux et principes du traitement chirurgical","q":"Quels sont les objectifs du traitement de l'artériopathie oblitérante des membres inférieurs (AOMI) ?","a":"<p>Le traitement de l'AOMI a deux objectifs principaux :</p><ul><li>Une visée générale : améliorer le <strong>pronostic cardiovasculaire et vital</strong>.</li><li>Une visée locale : <strong>résoudre les symptômes</strong> et améliorer le <strong>pronostic du membre</strong>.</li></ul>"},{"i":"d3c88e0ebc69","n":225,"o":"225-5","u":"Prise en charge","t":"Connaître le traitement médical : traitement médicamenteux et principes du traitement chirurgical","q":"Quelles sont les mesures générales non médicamenteuses recommandées pour la prise en charge de l'artériopathie oblitérante des membres inférieurs (AOMI) ?","a":"<p>Les mesures générales incluent :</p><ul><li>La prise en charge des <strong>facteurs de risque cardiovasculaires (FRCV)</strong>, notamment l'<strong>arrêt du tabac</strong> et le contrôle du diabète.</li><li>La <strong>marche / réadaptation supervisée</strong> : <strong>30-45 minutes</strong>, <strong>≥ 3 fois/semaine</strong>, pour favoriser la circulation collatérale.</li><li>Les <strong>soins de plaies</strong>, sous la supervision d'une équipe multidisciplinaire spécialisée.</li></ul>"},{"i":"da60e784baec","n":225,"o":"225-5","u":"Prise en charge","t":"Connaître le traitement médical : traitement médicamenteux et principes du traitement chirurgical","q":"Quand l'amputation est-elle envisagée dans la prise en charge de l'artériopathie oblitérante des membres inférieurs (AOMI) et quels sont ses principes ?","a":"<p>L'amputation est le <strong>geste ultime</strong>, envisagé à défaut de toute possibilité de revascularisation. Elle est réalisée en <strong>zone saine et bien oxygénée</strong> (intérêt de la TcPO2), en sauvegardant autant que possible l'appui et l'articulation du genou pour faciliter l'appareillage par prothèse.</p>"},{"i":"f2bea3201b77","n":225,"o":"225-5","u":"Prise en charge","t":"Connaître le traitement médical : traitement médicamenteux et principes du traitement chirurgical","q":"Quels sont les traitements médicamenteux essentiels dans la prise en charge de l'artériopathie oblitérante des membres inférieurs (AOMI) et leurs objectifs ?","a":"<p>Les traitements médicamenteux essentiels sont :</p><ul><li>Les <strong>antiplaquettaires</strong> (aspirine) : à dose antiagrégante, indication discutée si AOMI asymptomatique isolée.</li><li>Les <strong>statines</strong> : objectif <strong>LDL < 0,55 g/L</strong> et réduction ≥ 50 % de la valeur initiale.</li><li>Les <strong>IEC</strong> : objectif <strong>PA < 140/90 mmHg</strong>, intérêt pronostique même sans HTA.</li><li>Les <strong>bêta-bloquants</strong> : à utiliser avec prudence si ischémie critique non revascularisable, possibles si indication formelle (cardiopathie ischémique, IC à FE altérée).</li><li>Les <strong>prostaglandines</strong> : proposées en cas d'ischémie critique non revascularisable (perfusions quotidiennes en milieu spécialisé).</li></ul>"},{"i":"23d5e1331f54","n":225,"o":"225-6","u":"Suivi et/ou pronostic","t":"Connaître les complications et le pronostic : ischémie aigüe des membres inférieurs, morbimortalité cardiovasculaire","q":"Quel est le rôle de l'Indice de Pression Systolique (IPS) dans l'évaluation du risque cardiovasculaire chez un patient atteint d'AOMI ?","a":"<p>Un <strong>IPS &lt; 0,90</strong> est un <strong>marqueur de risque cardiovasculaire élevé</strong>. Il est associé à un risque accru d'évènements cardiovasculaires majeurs (accident coronarien ou cérébral fatal ou non).</p>"},{"i":"2b11fd4097c3","n":225,"o":"225-6","u":"Suivi et/ou pronostic","t":"Connaître les complications et le pronostic : ischémie aigüe des membres inférieurs, morbimortalité cardiovasculaire","q":"Pourquoi dit-on que le pronostic vital de l'artériopathie oblitérante des membres inférieurs (AOMI) est principalement conditionné par la morbimortalité cardiovasculaire ?","a":"<p>L'AOMI est l'expression locale d'une <strong>maladie athéromateuse systémique</strong>. Le pronostic vital est avant tout conditionné par les <strong>atteintes coronariennes</strong> et <strong>cérébrovasculaires</strong> associées, qui sont souvent présentes et doivent être recherchées.</p>"},{"i":"a71c2838ba51","n":225,"o":"225-6","u":"Suivi et/ou pronostic","t":"Connaître les complications et le pronostic : ischémie aigüe des membres inférieurs, morbimortalité cardiovasculaire","q":"Quelle est la principale complication aiguë locale de l'artériopathie oblitérante des membres inférieurs (AOMI) et comment survient-elle ?","a":"<p>La principale complication aiguë locale de l'AOMI est l'<strong>ischémie aiguë de membre</strong>. Elle survient principalement par <strong>thrombose in situ</strong> d'une lésion d'AOMI préexistante.</p>"},{"i":"c23ad153d651","n":225,"o":"225-6","u":"Suivi et/ou pronostic","t":"Connaître les complications et le pronostic : ischémie aigüe des membres inférieurs, morbimortalité cardiovasculaire","q":"Quel est le pronostic en termes de mortalité et de risque d'amputation pour un patient atteint d'ischémie permanente chronique liée à une AOMI ?","a":"<ul><li>La mortalité est de <strong>25 % à 1 an</strong> et de <strong>70 % à 5 ans</strong>.</li><li>Le risque d'amputation du membre inférieur est d'environ <strong>5 % à 5 ans</strong>, notamment en cas de mauvais contrôle des facteurs de risque cardiovasculaire.</li></ul>"},{"i":"f7706853d44c","n":225,"o":"225-6","u":"Suivi et/ou pronostic","t":"Connaître les complications et le pronostic : ischémie aigüe des membres inférieurs, morbimortalité cardiovasculaire","q":"Quel est le pronostic en termes d'espérance de vie et de mortalité à 5 ans pour un patient présentant une claudication intermittente due à une AOMI ?","a":"<ul><li>L'espérance de vie est <strong>réduite de -10 ans</strong>.</li><li>La mortalité à 5 ans est de <strong>15 %</strong> si elle évolue vers une ischémie d'effort.</li></ul>"},{"i":"212d3456c713","n":225,"o":"225-7","u":"Diagnostic positif","t":"Savoir définir et identifier les manifestations cliniques d’ischémie aiguë complète ou incomplète","q":"Quels sont les signes cliniques indiquant une ischémie aiguë menaçante ou irréversible selon la classification de Rutherford ?","a":"<ul><li><strong>Ischémie menaçante (Grade IIa-IIb)</strong> : présence d'un déficit sensitif (limité aux orteils ou au-delà) et/ou d'un déficit moteur modéré.</li><li><strong>Ischémie irréversible (Grade III)</strong> : présence d'une <strong>anesthésie importante</strong> et d'une <strong>paralysie</strong> importante. D'autres signes d'ischémie dépassée incluent la <strong>rigidité musculaire</strong>, les <strong>marbrures</strong> et les <strong>phlyctènes</strong>.</li></ul>"},{"i":"2d7b3ef64466","n":225,"o":"225-7","u":"Diagnostic positif","t":"Savoir définir et identifier les manifestations cliniques d’ischémie aiguë complète ou incomplète","q":"Quels sont les signes fonctionnels et physiques d'une ischémie aiguë d'un membre ?","a":"<ul><li><strong>Signes fonctionnels</strong> : douleur spontanée brutale à type de <strong>broiement</strong>, impotence fonctionnelle du membre.</li><li><strong>Signes physiques</strong> : membre <strong>froid, pâle, livide</strong>, et <strong>abolition des pouls</strong> en aval de l'occlusion.</li></ul>"},{"i":"2f7e3e07b47f","n":225,"o":"225-7","u":"Diagnostic positif","t":"Savoir définir et identifier les manifestations cliniques d’ischémie aiguë complète ou incomplète","q":"Quelle est la définition de l'ischémie aiguë d'un membre ?","a":"<p>L'ischémie aiguë d'un membre correspond à une interruption brutale du flux artériel, entraînant une ischémie tissulaire qui peut aboutir à une nécrose. Il s'agit d'une urgence absolue.</p>"},{"i":"60957646eb54","n":225,"o":"225-7","u":"Diagnostic positif","t":"Savoir définir et identifier les manifestations cliniques d’ischémie aiguë complète ou incomplète","q":"Quels sont les délais de souffrance tissulaire des différentes cellules lors d'une ischémie aiguë d'un membre ?","a":"<ul><li>Cellules nerveuses : <strong>moins de 2 heures</strong>.</li><li>Cellules musculaires : <strong>6 à 8 heures</strong>.</li><li>Nécrose cutanée : à partir de <strong>24 heures</strong>.</li></ul>"},{"i":"71e6120491ad","n":225,"o":"225-7","u":"Diagnostic positif","t":"Savoir définir et identifier les manifestations cliniques d’ischémie aiguë complète ou incomplète","q":"Comment différencier cliniquement une ischémie aiguë complète d'une ischémie aiguë incomplète d'un membre ?","a":"<p>L'<strong>ischémie complète</strong> est caractérisée par la présence d'une <strong>paralysie</strong>, c'est-à-dire l'impossibilité de mobiliser les orteils ou de relever le pied (atteinte du nerf fibulaire commun). Son absence signe l'ischémie incomplète.</p>"},{"i":"20825a6b1528","n":225,"o":"225-9","u":"Identifier une urgence","t":"Connaître les principes d’un traitement en urgence","q":"Quel bilan étiologique et traitement au long cours sont préconisés après la revascularisation d'une ischémie aiguë de membre ?","a":"<p>Après revascularisation, un bilan étiologique et un traitement au long cours sont nécessaires :</p><ul><li><strong>Bilan étiologique</strong> : étiologie cardiaque (<strong>Holter, ETT ± ETO</strong>) et artérielle (<strong>écho-Doppler</strong>).</li><li><strong>Traitement de la cause</strong> : <strong>anticoagulation au long cours si Fibrillation Auriculaire (FA)</strong>, ou <strong>antiagrégant plaquettaire et contrôle des FRCV</strong> (Facteurs de Risque Cardiovasculaires) si l'origine est thrombotique.</li></ul>"},{"i":"2da7d4f5e4c4","n":225,"o":"225-9","u":"Identifier une urgence","t":"Connaître les principes d’un traitement en urgence","q":"Quelles sont les techniques de revascularisation privilégiées selon la cause de l'ischémie aiguë de membre ?","a":"<p>Les techniques de revascularisation varient selon la cause :</p><ul><li>Pour une <strong>embolie sur artères saines</strong> : une <strong>embolectomie par sonde de Fogarty</strong> sous contrôle angiographique.</li><li>Pour une <strong>thrombose sur artère pathologique</strong> : des techniques <strong>conventionnelles</strong> (endartériectomie, pontage) ou <strong>endovasculaires</strong> (recanalisation, angioplastie, thrombo-aspiration).</li><li>La <strong>thrombolyse in situ</strong> est une option, mais elle est <strong>contre-indiquée</strong> si l'ischémie est sensitivo-motrice en raison d'un délai d'action trop long et d'un caillot volumineux.</li></ul>"},{"i":"3284541ea3e8","n":225,"o":"225-9","u":"Identifier une urgence","t":"Connaître les principes d’un traitement en urgence","q":"Quel est le traitement préventif et curatif du syndrome de revascularisation ?","a":"<p>Le traitement et la surveillance du syndrome de revascularisation comprennent :</p><ul><li>Surveillance rapprochée de la diurèse, de l'ionogramme, de l'urée, de la créatinine et des CPK.</li><li><strong>Alcalinisation</strong> de l'acidose métabolique par <strong>bicarbonates IV</strong>.</li><li>Administration d'un <strong>chélateur de potassium</strong> pour l'hyperkaliémie.</li><li>Voire dialyse et lavage de membre dans les cas sévères.</li></ul>"},{"i":"3fae9e92604f","n":225,"o":"225-9","u":"Identifier une urgence","t":"Connaître les principes d’un traitement en urgence","q":"Quel est le traitement médical immédiat de première intention pour une ischémie aiguë de membre, avant revascularisation ?","a":"<p>Le traitement médical immédiat comprend :</p><ul><li>Une <strong>anticoagulation</strong> par <strong>héparine non fractionnée</strong> (bolus puis perfusion continue avec TCA cible de 2-3), après bilan de coagulation.</li><li>Une <strong>antalgie</strong>, avec des antalgiques de <strong>niveau 3</strong> souvent nécessaires d'emblée.</li><li>Des mesures associées : <strong>oxygénothérapie nasale</strong> et équilibration hémodynamique (remplissage) si besoin.</li><li>Des soins locaux : éviter tout point de compression (protection mousse/coton, position légèrement déclive), proscrire frottements et adhésifs sur la peau ischémique.</li></ul>"},{"i":"5b3e5b667ecb","n":225,"o":"225-9","u":"Identifier une urgence","t":"Connaître les principes d’un traitement en urgence","q":"Dans quel cas et pourquoi une aponévrotomie jambière est-elle indiquée ou discutée dans la prise en charge de l'ischémie aiguë de membre ?","a":"<p>Une aponévrotomie jambière est indiquée en cas de <strong>syndrome des loges</strong> avéré. Elle est également discutée systématiquement si la revascularisation est <strong>tardive</strong>, en prévention du syndrome des loges ou de ses conséquences.</p>"},{"i":"7db8d0aace5e","n":225,"o":"225-9","u":"Identifier une urgence","t":"Connaître les principes d’un traitement en urgence","q":"Quand une amputation est-elle indiquée dans la prise en charge de l'ischémie aiguë de membre ?","a":"<p>L'amputation est indiquée :</p><ul><li><strong>D'emblée si l'ischémie est dépassée</strong> (grade III de l'ischémie).</li><li><strong>Secondairement</strong> si les tentatives de revascularisation échouent ou si des complications sont irréversibles.</li></ul>"},{"i":"a3bafcd188e4","n":225,"o":"225-9","u":"Identifier une urgence","t":"Connaître les principes d’un traitement en urgence","q":"Quelles sont les principales complications métaboliques et rénales du syndrome de revascularisation après ischémie aiguë de membre ?","a":"<p>Le syndrome de revascularisation peut causer :</p><ul><li><strong>Hyperkaliémie</strong></li><li><strong>Hyperuricémie</strong></li><li><strong>Hyperphosphorémie</strong></li><li><strong>Acidose métabolique</strong></li><li><strong>Hypocalcémie</strong></li><li><strong>Myoglobinémie / Myoglobinurie</strong></li><li><strong>CIVD</strong> (Coagulation Intravasculaire Disséminée)</li><li><strong>Insuffisance rénale aiguë</strong> par nécrose tubulaire aiguë.</li></ul>"},{"i":"ad541ce1a062","n":225,"o":"225-9","u":"Identifier une urgence","t":"Connaître les principes d’un traitement en urgence","q":"Quel est le délai impératif de revascularisation en cas d'ischémie aiguë de membre ?","a":"<p>La revascularisation doit être effectuée dans les <strong>6 heures</strong> suivant le début du tableau clinique pour une ischémie aiguë de membre.</p>"}]};